import React from 'react';
import { useTranslation } from 'react-i18next';

/**
 * UserStatusDot
 * Accessible, dynamic status indicator dot for user accounts.
 *
 * Requirements:
 * - Displays ONLY the colored indicator dot (no visible text label)
 * - Color Mapping:
 *   - Active    → Green dot (bg-emerald-500)
 *   - Inactive  → Red dot (bg-red-500)
 *   - Suspended → Amber dot (bg-amber-500)
 * - Preserves accessibility via aria-label, role="status", title tooltip, and screen-reader text
 */
export const UserStatusDot = ({
  status = 'active',
  size = 'md',
  className = '',
  showPulse = true,
  title = null,
}) => {
  const { t } = useTranslation();
  const normalized = (status || 'active').toLowerCase().trim();

  let dotColor = 'bg-emerald-500';
  let haloClass = 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 ring-1 ring-emerald-500/30';
  let label = t('common.active', 'Active');
  let hasPulse = showPulse;

  if (normalized === 'inactive') {
    dotColor = 'bg-red-500';
    haloClass = 'bg-red-500/15 text-red-700 dark:text-red-400 ring-1 ring-red-500/30';
    label = t('common.inactive', 'Inactive');
    hasPulse = false;
  } else if (normalized === 'suspended') {
    dotColor = 'bg-amber-500';
    haloClass = 'bg-amber-500/15 text-amber-700 dark:text-amber-400 ring-1 ring-amber-500/30';
    label = t('common.suspended', 'Suspended');
    hasPulse = false;
  }

  const tooltipTitle = title || label;

  // Size configurations
  // sm: 6px dot inside 14px halo
  // md: 8px dot inside 18px halo
  // lg: 10px dot inside 22px halo
  const sizeMap = {
    sm: {
      wrapper: 'w-4 h-4',
      dot: 'w-1.5 h-1.5',
    },
    md: {
      wrapper: 'w-5 h-5',
      dot: 'w-2 h-2',
    },
    lg: {
      wrapper: 'w-6 h-6',
      dot: 'w-2.5 h-2.5',
    },
  };

  const currentSize = sizeMap[size] || sizeMap.md;

  return (
    <span
      className={`inline-flex items-center justify-center rounded-full ${currentSize.wrapper} ${haloClass} select-none shrink-0 transition-all ${className}`}
      title={tooltipTitle}
      aria-label={tooltipTitle}
      role="status"
    >
      <span
        className={`rounded-full ${currentSize.dot} ${dotColor} ${
          hasPulse ? 'motion-safe:animate-pulse' : ''
        } shadow-xs shrink-0`}
      />
      <span className="sr-only">{tooltipTitle}</span>
    </span>
  );
};

export default UserStatusDot;

import { useState } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RefreshCw, Shield, User, Check } from 'lucide-react';
import toast from 'react-hot-toast';
import AvatarUpload from '@/components/users/AvatarUpload';
import { getRoleLabel } from '@/lib/roleUtils';
import { useAuth } from '@/contexts/AuthContext';
import { useTranslation } from '@/i18n';

const AddUserModal = ({ isOpen, onClose, onSave, projects = [], roles = [] }) => {
  const { isSuperAdmin } = useAuth();
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState('account'); // 'account' | 'access'
  const [loading, setLoading] = useState(false);
  const [projectSearch, setProjectSearch] = useState('');

  const defaultRoles = [
    { code: 'STAFF', name: 'Staff / Requester', description: 'Withdraw items, view stock for assigned projects only' },
    { code: 'SUPERVISOR', name: 'Supervisor / Approver', description: 'Approve withdrawal requests and view project-level reports' },
    { code: 'ADMIN', name: 'Administrator', description: 'Full permissions: approve withdrawals, manage projects and users' },
    { code: 'SUPER', name: 'System Administrator', description: 'System-level access: manage everything including admins, permissions, system settings, security, integrations' }
  ];

  const rawRoles = roles.length > 0 ? roles : defaultRoles;
  const availableRoles = rawRoles.filter(r => {
    const code = (r.code || '').toUpperCase();
    if (code === 'SUPER' && !isSuperAdmin) return false;
    return true;
  });

  const [formData, setFormData] = useState({
    email: '',
    full_name: '',
    phone: '',
    position: '',
    avatar_url: '',
    avatar_file: null,
    role: 'staff',
    role_id: null,
    status: 'active',
    access_type: 'all', // 'all' | 'selected'
    selected_projects: [],
    send_invitation: false
  });



  const handleProjectToggle = (projectId) => {
    setFormData(prev => {
      const exists = prev.selected_projects.includes(projectId);
      return {
        ...prev,
        selected_projects: exists
          ? prev.selected_projects.filter(id => id !== projectId)
          : [...prev.selected_projects, projectId]
      };
    });
  };

  const handleSelectAllProjects = () => {
    setFormData(prev => ({
      ...prev,
      selected_projects: projects.map(p => p.id)
    }));
  };

  const handleClearAllProjects = () => {
    setFormData(prev => ({
      ...prev,
      selected_projects: []
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.email || !formData.full_name) {
      toast.error('Please enter email and full name');
      return;
    }

    if (formData.access_type === 'selected' && formData.selected_projects.length === 0) {
      toast.error('Please select at least 1 project for selected projects access');
      setActiveTab('access');
      return;
    }

    try {
      setLoading(true);
      const matchedRole = availableRoles.find(r => 
        (formData.role_id && r.id === formData.role_id) || 
        (r.code || '').toLowerCase() === (formData.role || '').toLowerCase() ||
        (['STAFF', 'REQUESTER'].includes(r.code) && ['staff', 'operator', 'requester'].includes(formData.role?.toLowerCase()))
      ) || null;
      await onSave({
        email: formData.email.trim(),
        full_name: formData.full_name.trim(),
        phone: formData.phone.trim() || null,
        position: formData.position.trim() || null,
        avatar_url: formData.avatar_url || null,
        avatar_file: formData.avatar_file || null,
        role: formData.role,
        role_id: matchedRole?.id || null,
        roleName: matchedRole?.name || getRoleLabel(formData.role),
        status: formData.status,
        all_projects: formData.access_type === 'all',
        project_ids: formData.access_type === 'all' ? [] : formData.selected_projects,
        send_invitation: formData.send_invitation
      });
      resetForm();
      onClose();
    } catch (error) {

      console.error('Create User Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      email: '',
      full_name: '',
      phone: '',
      position: '',
      avatar_url: '',
      avatar_file: null,
      role: 'staff',
      role_id: null,
      status: 'active',
      access_type: 'all',
      selected_projects: [],
      send_invitation: false
    });
    setActiveTab('account');
    setProjectSearch('');
  };

  const filteredProjects = projects.filter(p => 
    (p.name || '').toLowerCase().includes(projectSearch.toLowerCase()) ||
    (p.project_code || '').toLowerCase().includes(projectSearch.toLowerCase())
  );


  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) { resetForm(); onClose(); } }}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-card text-card-foreground rounded-xl border border-border shadow-xl">
        <DialogHeader>
          <DialogTitle className="text-xl font-bold flex items-center gap-2">
            <User className="w-5 h-5 text-primary" />
            {t('users.addUser')}
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {t('users.subtitle')}
          </DialogDescription>
        </DialogHeader>

        {/* Tab Selector */}
        <div className="flex border-b border-border mb-4 overflow-x-auto scrollbar-none">
          <button
            type="button"
            onClick={() => setActiveTab('account')}
            className={`shrink-0 flex items-center gap-2 px-3.5 sm:px-4 py-2 text-sm font-medium border-b-2 transition-colors whitespace-nowrap min-h-[40px] cursor-pointer ${
              activeTab === 'account'
                ? 'border-primary text-primary font-semibold'
                : 'border-transparent text-muted-foreground hover:text-foreground'
