/**
 * Dispatches transactional email notifications for the equipment borrow/return
 * (/checkouts) lifecycle:
 * - checkout_submitted:   notify approvers/administrators about a new pending request
 * - checkout_approved:    notify the borrower that the request was approved
 * - checkout_rejected:    notify the borrower, including the rejection reason
 * - checkout_handed_over: notify the borrower that equipment was physically handed over
 * - checkout_returned:    notify the borrower that returned equipment was recorded
 *
 * `checkout_due_soon` and `checkout_overdue` are dispatched by the scheduled
 * api/checkouts-cron.js function instead, because no user action triggers them.
 */
export const dispatchCheckoutNotification = async ({
  eventType,
  orderId,
  orderData: preloadedOrder = null,
  approverName = '',
  rejectionReason = '',
  extraData = {}
}) => {
  if (!eventType || !orderId) {
    return { success: false, reason: 'INVALID_ARGUMENTS' };
  }

  // Suppression hook so a single user action can avoid a duplicate email
  // (e.g. an approver borrowing for themselves triggers both approved + handover).
  if (extraData.suppress) {
    return { success: true, skipped: 'SUPPRESSED' };
  }

  const cacheKey = eventType === 'checkout_returned' && !extraData?.returnsCompleted
    ? `${eventType}:${orderId}:${extraData?.returnedAt || Date.now()}`
    : `${eventType}:${orderId}`;
  if (dispatchedEventsCache.has(cacheKey)) {
    return { success: true, deduplicated: true };
  }

  try {
    // 1. Fetch system settings
    const { notificationEvents, branding } = await fetchNotificationSettings();

    const eventConfig = notificationEvents[eventType];
    if (eventConfig && eventConfig.enabled === false) {
      return { success: true, skipped: 'EVENT_DISABLED' };
    }

    // 2. Fetch full checkout order details if not preloaded
    let order = preloadedOrder;
    if (!order || !order.projects) {
      const { data: fetchedOrder, error: orderErr } = await supabase
        .from('checkout_orders')
        .select(`
          *,
          projects:project_id (id, name, project_code)
        `)
        .eq('id', orderId)
        .maybeSingle();

      if (orderErr || !fetchedOrder) {
        console.warn('[NotificationDispatcher] Checkout order fetch error:', orderErr?.message);
        return { success: false, reason: 'ORDER_NOT_FOUND' };
      }
      order = fetchedOrder;
    }

    // 3. Always read line items from the database: callers pass shapes that
    // differ from the DB row shape (POS payload uses quantity/item_id and has no
    // embedded item name), so the DB is the single source of truth here.
    const { data: fetchedItems, error: itemsErr } = await supabase
      .from('checkout_items')
      .select(`
        id, quantity_borrowed, quantity_returned, serial_number, condition_on_checkout,
        items:item_id (id, name, sku, unit)
      `)
      .eq('checkout_order_id', orderId);

    if (itemsErr) {
      console.warn('[NotificationDispatcher] Checkout items fetch error:', itemsErr.message);
    }

    const dueDate = formatThaiDateOrDateTime(order.expected_return_date);
    const items = buildCheckoutEmailItems(fetchedItems || [], {
      dueDate,
      condition: extraData.condition ? formatReturnCondition(extraData.condition) : '',
    });

    // 4. Resolve recipient emails (auth.users via RPC; profiles has no email column)
    const defaults = CHECKOUT_EVENT_DEFAULTS[eventType] || {};
    const targetRoles = eventConfig?.roles || defaults.roles || ['ADMIN', 'SUPERVISOR'];
    const recipientEmails = new Set();

    const adminRoles = targetRoles.filter((role) => role !== 'STAFF');
    const searchRoles = adminRoles.length > 0
      ? adminRoles
      : (eventConfig ? [] : ['ADMIN', 'SUPERVISOR', 'SUPER']);

    const resolvedUsers = await resolveUserEmails({
      userIds: order.borrower_id ? [order.borrower_id] : null,
      roles: searchRoles,
    });
    const borrowerEmail = resolvedUsers.find((user) => user.user_id === order.borrower_id)?.email || '';

    const borrowerDirected = ['checkout_approved', 'checkout_rejected', 'checkout_handed_over', 'checkout_returned'];
    if (borrowerEmail && (defaults.includeBorrower || borrowerDirected.includes(eventType))) {
      recipientEmails.add(borrowerEmail.trim());
    }

    if (searchRoles.length > 0) {
      emailsForRoles(resolvedUsers, searchRoles).forEach((user) => {
        if (user.email) recipientEmails.add(user.email.trim());
      });
    }

    parseEmailList(eventConfig?.to_extra).forEach((entry) => recipientEmails.add(entry));

    const validRecipients = [...recipientEmails].filter(isValidEmail);

    if (!validRecipients.length) {
      return { success: true, skipped: 'NO_VALID_RECIPIENTS' };
    }

    // 5. Build template data payload shared by HTML, text and subject
    const appName = branding.app_name || 'StockFlow';
    const publicBaseUrl = normalizeBaseUrl(branding.public_base_url);
    const todayBangkok = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Bangkok' }).format(new Date());
    const approvedDate = formatThaiDateTime(order.approved_at || new Date().toISOString());
    const returnTimestamp = extraData.returnedAt || new Date().toISOString();

    const emailItems = items.map((item) => ({
      ...item,
      due_date: dueDate,
      condition: extraData.condition ? formatReturnCondition(extraData.condition) : '',
    }));

    const emailData = {
      event_type: eventType,
      app_name: appName,
      checkout_id: order.order_number || `CHK-${String(order.id || '').slice(0, 8).toUpperCase()}`,
      borrower_name: order.borrower_name || 'ผู้ขอยืม',
      borrower_department: order.borrower_department || '-',
      borrower_phone: order.borrower_phone || '-',
      project_name: order.projects?.name || 'โครงการทั่วไป',
      project_code: order.projects?.project_code || '-',
      equipment_name: emailItems[0]?.name || '-',
      asset_code: emailItems[0]?.asset_code || '-',
      quantity: `${emailItems.reduce((sum, item) => sum + (Number(item.requested_qty) || 0), 0)} ${emailItems[0]?.unit || 'ชิ้น'}`,
      checkout_date: formatThaiDateTime(order.checkout_date || order.created_at),
      due_date: dueDate,
      return_date: extraData.returnsCompleted ? formatThaiDateTime(returnTimestamp) : '',
      days_overdue: extraData.daysOverdue || '',
      approver_name: approverName || order.approved_by_name || 'เจ้าหน้าที่คลัง',
      reject_reason: rejectionReason || order.rejection_reason || '',
      condition: extraData.condition ? formatReturnCondition(extraData.condition) : '',
      condition_details: extraData.conditionDetails || '',
      public_base_url: publicBaseUrl,
      // Legacy withdrawal-style aliases kept in the shared data contract
      request_no: order.order_number || `CHK-${String(order.id || '').slice(0, 8).toUpperCase()}`,
      requester_name: order.borrower_name || 'ผู้ขอยืม',
      requester_email: borrowerEmail || '',
      user_name: order.borrower_name || 'ผู้ขอยืม',
      approved_by: approverName || order.approved_by_name || 'เจ้าหน้าที่ผู้จ่ายพัสดุ',
      rejected_by: approverName || order.rejected_by_name || 'เจ้าหน้าที่',
      rejection_reason: rejectionReason || order.rejection_reason || '',
      approved_date: approvedDate,
      rejected_date: formatThaiDateTime(order.rejected_at || new Date().toISOString()),
      status: defaults.status || order.status || '',
      fulfillment_status: order.status || 'รอพิจารณา',
      item_count: `${emailItems.length} รายการ`,
      total_quantity: `${emailItems.reduce((sum, item) => sum + (Number(item.requested_qty) || 0), 0)} ${emailItems[0]?.unit || 'ชิ้น'}`,
      purpose: order.purpose || '-',
      note: order.notes || '',
      generated_date: todayBangkok,
      action_url: buildActionUrl(publicBaseUrl, `/checkouts?order_id=${encodeURIComponent(order.order_number || order.id)}`),
      items: emailItems,
    };

    // 6. Render HTML, plain-text fallback, and the variable-resolved subject
    const template = eventConfig || {};
    const html = renderEmailHtml({ branding, template, data: emailData });
    const plainText = renderEmailText({ branding, template, data: emailData });
    const fallbackSubject = defaults.fallbackSubject
      ? defaults.fallbackSubject(emailData)
      : `${appName} — ${eventType}`;
    const subject = resolveSubject(template.subject, fallbackSubject, emailData);

    // 7. CC routing: event cc_roles (e.g. administrator on overdue) + cc_extra,
    //    never duplicating someone already in the To list.
    const ccCandidates = new Set();
    const ccRoles = eventConfig?.cc_roles || defaults.ccRoles || [];
    if (ccRoles.length > 0) {
      const ccUsers = await resolveUserEmails({ roles: ccRoles });
      emailsForRoles(ccUsers, ccRoles).forEach((user) => {
        if (user.email) ccCandidates.add(user.email.trim());
      });
    }
    parseEmailList(eventConfig?.cc_extra).forEach((email) => ccCandidates.add(email));

    const toSet = new Set(validRecipients);
    const ccList = [...ccCandidates].filter((email) => !toSet.has(email) && EMAIL_REGEX.test(email));

    // 8. Send transactional email
    await sendStockFlowEmail({
      to: validRecipients,
      cc: ccList.length ? ccList : undefined,
      subject,
      html,
      text: plainText,
      eventType,
      actionUrl: emailData.action_url,
    });

    dispatchedEventsCache.add(cacheKey);
    return { success: true, dispatched: true, recipientCount: validRecipients.length, ccCount: ccList.length };
  } catch (err) {
    console.error('[NotificationDispatcher] dispatchCheckoutNotification error:', err);
    return { success: false, error: err.message };
  }
};

const REVERT_EMAIL_BADGE = {
  withdrawal_reverted: 'ย้อนสถานะคำขอเบิก',
  checkout_reverted: 'ย้อนสถานะรายการยืม',
};

const formatDateOnlyValue = (value) => {
  if (!value) return '-';
  return formatThaiDateOrDateTime(String(value).slice(0, 10));
};

/**
 * Dispatches the "a SUPER reverted this record" email for withdrawals and
 * checkouts. Deliberately not cached: an order can be reverted, re-approved and
 * reverted again, and each reverse transition is a distinct auditable event.
 */
export const dispatchRevertNotification = async ({
  eventType,
  orderId,
  kind = 'withdrawal',
  actorName = '',
  reason = '',
  previousStatus = '',
  newStatus = '',
}) => {
  if (!eventType || !orderId) {
    return { success: false, reason: 'INVALID_ARGUMENTS' };
  }

  try {
    const { notificationEvents, branding } = await fetchNotificationSettings();
    const eventConfig = notificationEvents[eventType];
    if (eventConfig && eventConfig.enabled === false) {
      return { success: true, skipped: 'EVENT_DISABLED' };
    }

    const isCheckout = kind === 'checkout';
    let order;
    if (isCheckout) {
      const { data, error } = await supabase
        .from('checkout_orders')
        .select('*, projects:project_id (id, name, project_code)')
        .eq('id', orderId)
        .maybeSingle();
      if (error || !data) {
        console.warn('[NotificationDispatcher] Revert checkout fetch error:', error?.message);
        return { success: false, reason: 'ORDER_NOT_FOUND' };
      }
      order = data;
    } else {
      const { data, error } = await supabase
        .from('withdrawal_orders')
        .select('*, projects:project_id (id, name, project_code), requester:requested_by (id, full_name)')
        .eq('id', orderId)
        .maybeSingle();
      if (error || !data) {
        console.warn('[NotificationDispatcher] Revert withdrawal fetch error:', error?.message);
        return { success: false, reason: 'ORDER_NOT_FOUND' };
      }
      order = data;
    }

    let items = [];
    if (isCheckout) {
      const { data, error } = await supabase
        .from('checkout_items')
        .select('id, quantity_borrowed, quantity_returned, serial_number, items:item_id (id, name, sku, unit)')
        .eq('checkout_order_id', orderId);
      if (error) {
        console.warn('[NotificationDispatcher] Revert checkout items fetch error:', error.message);
        return { success: false, reason: 'ITEMS_NOT_FOUND' };
      }
      items = buildCheckoutEmailItems(data || [], {});
    } else {
      const { data, error } = await supabase
        .from('withdrawal_items')
        .select('id, quantity, item:item_id (id, name, sku, unit)')
        .eq('order_id', orderId);
      if (error) {
        console.warn('[NotificationDispatcher] Revert withdrawal items fetch error:', error.message);
        return { success: false, reason: 'ITEMS_NOT_FOUND' };
      }
      items = (data || []).map((line) => ({
        name: line.item?.name || 'วัสดุ',
        sku: line.item?.sku || '-',
        unit: line.item?.unit || 'หน่วย',
        requested_qty: line.quantity,
        approved_qty: line.quantity,
      }));
    }

    const targetRoles = eventConfig?.roles || ['ADMIN', 'SUPER'];
    const actorIds = isCheckout
      ? [order.borrower_id, order.approved_by]
      : [order.requested_by, order.approved_by, order.rejected_by, order.completed_by];
    const resolvedUsers = await resolveUserEmails({
      userIds: [...new Set(actorIds.filter(Boolean))],
      roles: targetRoles.filter(role => role !== 'STAFF'),
    });

    const recipientEmails = new Set();
    const directUserId = isCheckout ? order.borrower_id : order.requested_by;
    const directEmail = resolvedUsers.find(user => user.user_id === directUserId)?.email || '';

    resolvedUsers.forEach(user => { if (user.email) recipientEmails.add(user.email.trim()); });
    emailsForRoles(resolvedUsers, targetRoles.filter(role => role !== 'STAFF'))
      .forEach(user => { if (user.email) recipientEmails.add(user.email.trim()); });
    parseEmailList(eventConfig?.to_extra).forEach(email => recipientEmails.add(email));

    const validRecipients = [...recipientEmails].filter(isValidEmail);
    if (!validRecipients.length) {
      return { success: true, skipped: 'NO_VALID_RECIPIENTS' };
    }

    const appName = branding.app_name || 'StockFlow';
    const publicBaseUrl = normalizeBaseUrl(branding.public_base_url);
    const orderNumber = order.order_number
      || (isCheckout ? 'CHK-' : 'WO-') + String(order.id).slice(0, 8).toUpperCase();
    const totalQuantity = items.reduce((sum, item) => sum + (Number(item.requested_qty) || 0), 0);

    const emailData = {
      event_type: eventType,
      app_name: appName,
      user_name: isCheckout ? (order.borrower_name || 'ผู้ขอยืม') : (order.requester?.full_name || 'ผู้ขอเบิก'),
      requester_name: isCheckout ? (order.borrower_name || 'ผู้ขอยืม') : (order.requester?.full_name || 'ผู้ขอเบิก'),
      requester_email: directEmail,
      request_no: orderNumber,
      checkout_id: orderNumber,
      borrower_name: order.borrower_name || 'ผู้ขอยืม',
      borrower_department: order.borrower_department || '-',
      borrower_phone: order.borrower_phone || '-',
      project_name: order.projects?.name || 'โครงการทั่วไป',
      project_code: order.projects?.project_code || '-',
      request_date: formatThaiDateTime(order.created_at || order.requested_at),
      checkout_date: formatThaiDateTime(order.checkout_date || order.created_at),
      due_date: formatDateOnlyValue(order.expected_return_date),
      status: String(newStatus || '').toUpperCase() || '-',
      status_badge: REVERT_EMAIL_BADGE[eventType] || '',
      fulfillment_status: String(newStatus || '').toUpperCase() || '-',
      previous_status: String(previousStatus || '').toUpperCase() || '-',
      new_status: String(newStatus || '').toUpperCase() || '-',
      reverted_by: actorName || 'SUPER',
      reverted_date: formatThaiDateTime(new Date().toISOString()),
      revert_reason: reason || '-',
      item_count: items.length + ' รายการ',
      total_quantity: totalQuantity + ' ' + (items[0]?.unit || 'หน่วย'),
      purpose: order.purpose || '-',
      note: order.notes || '',
      action_url: buildActionUrl(
        publicBaseUrl,
        isCheckout
          ? '/checkouts?tab=history&id=' + encodeURIComponent(order.id)
          : '/withdrawals?tab=orders&id=' + encodeURIComponent(order.id)
      ),
      items,
    };

    const template = { ...(eventConfig || {}), event_type: eventType };
    const html = renderEmailHtml({ branding, template, data: emailData });
    const text = renderEmailText({ branding, template, data: emailData });
    const fallbackSubject = '[' + appName + '] ' + (isCheckout ? 'รายการยืม ' : 'คำขอเบิก ')
      + orderNumber + ' ถูกย้อนสถานะเป็น ' + emailData.new_status;
    const subject = resolveSubject(eventConfig?.subject, fallbackSubject, emailData);

    const ccList = parseEmailList(eventConfig?.cc_extra, { exclude: validRecipients });
    await sendStockFlowEmail({
      to: validRecipients,
      cc: ccList.length ? ccList : undefined,
      subject,
      html,
      text,
      eventType,
      actionUrl: emailData.action_url,
    });

    return { success: true, dispatched: true, recipientCount: validRecipients.length, ccCount: ccList.length };
  } catch (err) {
    console.error('[NotificationDispatcher] dispatchRevertNotification error:', err);
    return { success: false, error: err.message };
  }
};

import { useEffect, useState, useRef, useCallback, useMemo } from 'react';
import { supabase } from '@/lib/supabase';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { 
  Search, Package, Tag, Building2, Edit3, Trash2, 
  LayoutGrid, List, RefreshCw, ImageIcon, Box, 
  SlidersHorizontal, CheckCircle2, AlertCircle, ChevronLeft, ChevronRight,
  ArrowRightLeft, Lock, Sparkles, History,
  ChevronDown, ArrowUpDown, ArrowUp, ArrowDown, CornerDownRight, FolderTree,
  MapPin, Plane
} from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import toast from 'react-hot-toast';
import { format } from 'date-fns';
import { ProjectLocationSelector } from '@/components/common/ProjectLocationSelector';
import { TransferItemDialog } from '@/components/items/TransferItemDialog';
import { ItemStockHistoryDialog } from '@/components/items/ItemStockHistoryDialog';
import { uploadFileToR2 } from '@/lib/r2Storage';
import { useTranslation } from '@/i18n';
import { isSchemaMismatchError, cleanRpcMessage } from '@/lib/rpcErrors';

const Items = () => {
  const { can, canAny, profile } = useAuth();
  const { t } = useTranslation();
  const [items, setItems] = useState([]);
  const [categories, setCategories] = useState([]);
  const [projectsList, setProjectsList] = useState([]);
  const [rawStockBalances, setRawStockBalances] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  // Filters & Layout States
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [projectFilter, setProjectFilter] = useState('all');
  const [viewMode, setViewMode] = useState('table'); // 'table' | 'grid'

  // Hierarchical & Sorting States
  const [sortConfig, setSortConfig] = useState({ key: 'name', direction: 'asc' });
  const [collapsedGroupKeys, setCollapsedGroupKeys] = useState(new Set());

  // Pagination States
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(25);
  const [pageInput, setPageInput] = useState('1');

  const [isEditOpen, setIsEditOpen] = useState(false);
  const [isDeleteOpen, setIsDeleteOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [allowItemDeletion, setAllowItemDeletion] = useState(true);
  const [allowDirectStockAdjustment, setAllowDirectStockAdjustment] = useState(false);
  const [hasTransactionConflict, setHasTransactionConflict] = useState(false);
  const [isTransferOpen, setIsTransferOpen] = useState(false);
  const [itemToTransfer, setItemToTransfer] = useState(null);
  const [formData, setFormData] = useState({ name: '', model: '', sku: '', source: '', vendor: '', category_id: '', unit: 'ชิ้น', description: '', image_url: '' });
  const [selectedItem, setSelectedItem] = useState(null);
  const [uploadingImage, setUploadingImage] = useState(false);
  const realtimeTimeoutRef = useRef(null);

  // Direct Stock Adjustment States in Edit Dialog
  const [adjustProjectId, setAdjustProjectId] = useState('');
  const [currentStockQty, setCurrentStockQty] = useState(0);
  const [newStockQty, setNewStockQty] = useState('');
  const [stockAdjustReason, setStockAdjustReason] = useState('');
  const [isAdjustingStock, setIsAdjustingStock] = useState(false);

  // Stock Adjustment History Dialog States
  const [isHistoryDialogOpen, setIsHistoryDialogOpen] = useState(false);
  const [selectedItemForHistory, setSelectedItemForHistory] = useState(null);
  const [adjustmentHistoryLogs, setAdjustmentHistoryLogs] = useState([]);
  const [loadingHistoryLogs, setLoadingHistoryLogs] = useState(false);

  const canAdjustStock = can('items.adjust_stock') && allowDirectStockAdjustment;
  const canTransferInventory = canAny(['inventory.transfer', 'inventory.manage']);

  const fetchSettings = useCallback(async () => {
    try {
      const { data, error } = await supabase
        .from('system_settings')
        .select('key, value')
        .in('key', ['allow_item_deletion', 'allow_direct_stock_adjustment']);

      if (!error && data) {
        data.forEach(setting => {
          if (setting.key === 'allow_item_deletion') {
            setAllowItemDeletion(Boolean(setting.value));
          } else if (setting.key === 'allow_direct_stock_adjustment') {
            setAllowDirectStockAdjustment(Boolean(setting.value));
          }
        });
      }
    } catch (err) {
      console.warn('[Items] Failed to fetch system_settings:', err);
    }
  }, []);

  const fetchCategories = useCallback(async () => {
    try {
      let { data, error } = await supabase.from('categories').select('id, name, description').order('name');
      if (error) throw error;

      if (!data || data.length === 0) {
        const defaultCats = [
          { name: t('items.categories.construction'), description: t('items.categories.constructionDesc') },
          { name: t('items.categories.electrical'), description: t('items.categories.electricalDesc') },
          { name: t('items.categories.plumbing'), description: t('items.categories.plumbingDesc') },
          { name: t('items.categories.tools'), description: t('items.categories.toolsDesc') },
          { name: t('items.categories.chemical'), description: t('items.categories.chemicalDesc') },
          { name: t('items.categories.miscellaneous'), description: t('items.categories.miscellaneousDesc') }
        ];
        const { data: seeded } = await supabase.from('categories').insert(defaultCats).select();
        if (seeded && seeded.length > 0) data = seeded;
      }
      setCategories(data || []);
    } catch (error) {
      console.error("Fetch Categories Error:", error);
    }
  }, [t]);

  const fetchItems = useCallback(async (isInitial = false) => {
    try {
      if (isInitial) {
        setLoading(true);
      } else {
        setRefreshing(true);
      }

      // Parallelize Supabase requests across items, stock_balance, and active projects
      const [itemsRes, stockRes, projectsRes] = await Promise.all([
        supabase
          .from('items')
          .select('id, name, model, sku, source, vendor, item_type, parent_sku, parent_id, seq_no, unit, description, notes, image_url, category_id, categories(name)')
          .order('name'),
        supabase
          .from('stock_balance')
          .select('project_id, item_id, item_name, unit, project_name, balance'),
        supabase
          .from('projects')
          .select('id, name, project_code, location, description, status')
          .eq('status', 'active')
      ]);

      if (itemsRes.error) throw itemsRes.error;

      const iData = itemsRes.data || [];
      const bData = stockRes.data || [];
      const pData = projectsRes.data || [];

      setProjectsList(pData);
      setRawStockBalances(bData);

      const projectMap = {};
      pData.forEach(p => { projectMap[p.id] = p; });

      const itemMap = {};
      iData.forEach(i => { itemMap[i.id] = i; });

      const records = [];

      // Construct project-specific stock balance records (only for active projects)
      bData.forEach(b => {
        const project = projectMap[b.project_id];
        // Exclude stock balance records belonging to deleted or inactive projects
        if (!project || project.status === 'inactive') {
          return;
        }

        // Balance rows must resolve to the canonical item master. The old
        // fallback rendered partial transfer rows with empty master metadata.
        const item = itemMap[b.item_id];
        if (!item) {
          console.warn('[Items] Ignoring stock balance with missing item master:', b.item_id);
          return;
        }

        // A warehouse row represents current inventory, not historical
        // activity. Once a transfer drains the source, stock_balance can
        // still expose the grouped source record at zero; do not render it
        // as an empty warehouse row.
        const balance = Number(b.balance);
        if (!Number.isFinite(balance) || balance <= 0) {
          return;
        }


        const projectCode = project.project_code || '';
        const projectName = project.name || b.project_name || '';
        const projectDisplay = projectCode ? `${projectCode} — ${projectName}` : (projectName || '-');

        const recordKey = `${b.item_id}_${b.project_id}`;
        if (records.some(record => record.recordKey === recordKey)) return;

        records.push({
          recordKey,
          id: item.id,
          project_id: b.project_id,
          name: item.name || 'Material Item',
          model: item.model || '-',
          sku: item.sku || '-',
          source: item.source || '',
          vendor: item.vendor || '',
          item_type: item.item_type || 'PARENT',
          parent_sku: item.parent_sku || '',
          parent_id: item.parent_id || null,
          seq_no: item.seq_no || null,
          category_name: item.categories?.name || '-',
          category_id: item.category_id,
          project_code: projectCode,
          project_name: projectName,
          project_location: project.location || '',
          project_display: projectDisplay,
          balance,
          unit: item.unit || b.unit || 'ชิ้น',
          description: item.description || item.notes || '',
          image_url: item.image_url || '',
          originalItem: item
        });
      });


      // Sort by item name then project name
      records.sort((a, b) => a.name.localeCompare(b.name, 'th'));
      setItems(records);
    } catch (error) {
      console.error("Fetch Items Error:", error);
      toast.error(t('items.toasts.loadCatalogFailed') + ': ' + (error.message || ''));
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  const triggerDebouncedFetch = useCallback(() => {
    if (realtimeTimeoutRef.current) {
      clearTimeout(realtimeTimeoutRef.current);
    }
    realtimeTimeoutRef.current = setTimeout(() => {
      fetchItems(false);
    }, 300);
  }, [fetchItems]);

  useEffect(() => {
    fetchItems(true);
    fetchCategories();
    fetchSettings();

    // Live Realtime synchronization on projects, items, transactions, and system_settings with debouncing
    const channel = supabase
      .channel('items-master-live-sync')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'projects' }, triggerDebouncedFetch)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'items' }, triggerDebouncedFetch)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'stock_in_orders' }, triggerDebouncedFetch)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'stock_in_items' }, triggerDebouncedFetch)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'stock_transactions' }, triggerDebouncedFetch)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'system_settings' }, () => {
        fetchSettings();
      })
      .subscribe();

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') {
        triggerDebouncedFetch();
        fetchSettings();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);

    const handleSettingsUpdated = () => void fetchSettings();
    window.addEventListener('stockflow:settings-updated', handleSettingsUpdated);

    return () => {
      if (realtimeTimeoutRef.current) {
        clearTimeout(realtimeTimeoutRef.current);
      }
      supabase.removeChannel(channel);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      window.removeEventListener('stockflow:settings-updated', handleSettingsUpdated);
    };
  }, [fetchItems, fetchCategories, fetchSettings, triggerDebouncedFetch]);

  const handleImageUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 5 * 1024 * 1024) {
      return toast.error(t('items.toasts.imageSizeExceeded'));
    }

    setUploadingImage(true);
    const toastId = toast.loading(t('items.toasts.uploadingImage'));

    try {
      const fileExt = file.name.split('.').pop()?.toLowerCase() || 'png';
      const safeItemName = (selectedItem?.sku || selectedItem?.id || 'item').replace(/[^a-zA-Z0-9_-]/g, '_');
      const customFileName = `item-${safeItemName}-${Date.now()}.${fileExt}`;

      const publicUrl = await uploadFileToR2(file, 'items', customFileName);
      if (publicUrl) {
        setFormData(prev => ({ ...prev, image_url: publicUrl }));
        toast.success(t('items.toasts.imageUploaded'), { id: toastId });
      } else {
        toast.error(t('items.toasts.imageUploadFailed'), { id: toastId });
      }
    } catch (err) {
      console.error('[Items] Image upload error:', err);
      toast.error(t('items.toasts.imageUploadError') + ': ' + (err.message || ''));
    } finally {
      setUploadingImage(false);
    }
  };

  const handleProjectChangeForAdjustment = (projId) => {
    setAdjustProjectId(projId);
    if (!selectedItem) return;
    const foundBalance = rawStockBalances.find(b => b.item_id === selectedItem.id && b.project_id === projId);
    const qty = foundBalance && foundBalance.balance !== undefined ? foundBalance.balance : 0;
    setCurrentStockQty(qty);
    setNewStockQty(String(qty));
    setStockAdjustReason('');
  };

  const openAdjustmentHistoryDialog = async (item) => {
    setSelectedItemForHistory(item);
    setIsHistoryDialogOpen(true);
    setLoadingHistoryLogs(true);
    try {
      const { data, error } = await supabase
        .from('stock_adjustment_logs')
        .select(`
          id,
          previous_quantity,
          new_quantity,
          difference,
          reason,
          created_at,
          projects:project_id (name, location, project_code),
          profiles:created_by (full_name)
        `)
        .eq('item_id', item.id)
        .order('created_at', { ascending: false });

      if (!error && data) {
        setAdjustmentHistoryLogs(data);
      } else {
        setAdjustmentHistoryLogs([]);
      }
    } catch (err) {
      console.warn('[Items] Failed to fetch stock adjustment logs:', err);
      setAdjustmentHistoryLogs([]);
    } finally {
      setLoadingHistoryLogs(false);
    }
  };

  const handleEditItem = async (e) => {
    e.preventDefault();
    try {
      setIsAdjustingStock(true);

      // Check stock adjustment first if requested
      const parsedNewStock = parseInt(newStockQty, 10);
      const isStockChanged = !isNaN(parsedNewStock) && parsedNewStock >= 0 && parsedNewStock !== currentStockQty;

      if (isStockChanged) {
        if (!allowDirectStockAdjustment) {
          toast.error(t('items.toasts.directAdjustmentDisabled'));
          setIsAdjustingStock(false);
          return;
        }
        if (!canAdjustStock) {
          toast.error(t('items.toasts.noAdjustPermission'));
          setIsAdjustingStock(false);
          return;
        }
        if (!adjustProjectId) {
          toast.error(t('items.toasts.selectProjectToAdjust'));
          setIsAdjustingStock(false);
          return;
        }
        if (!stockAdjustReason.trim()) {
          toast.error(t('items.toasts.reasonRequired'));
          setIsAdjustingStock(false);
          return;
        }
      }

      // 1. Build payload with only valid items columns (no updated_at — column doesn't exist)
      const updatePayload = {
        name: formData.name,
        model: formData.model || null,
        sku: formData.sku || null,
        source: formData.source || null,
        vendor: formData.vendor || null,
        category_id: formData.category_id || null,
        unit: formData.unit,
        description: formData.description || null,
        notes: formData.description || null,
        image_url: formData.image_url || null,
      };

      const { data: updatedRows, error: itemErr } = await supabase
        .from('items')
        .update(updatePayload)
        .eq('id', selectedItem.id)
        .select('id');

      if (itemErr) throw itemErr;

      if (!updatedRows || updatedRows.length === 0) {
        throw new Error('Update failed: 0 rows affected. You may not have permission to edit this item or the record was not found.');
      }

      // 2. Execute Stock Adjustment if changed
      if (isStockChanged) {
        const { data: rpcData, error: rpcError } = await supabase.rpc('adjust_item_current_stock', {
          p_item_id: selectedItem.id,
          p_project_id: adjustProjectId,
          p_new_quantity: parsedNewStock,
          p_reason: stockAdjustReason.trim(),
          p_actor_id: profile?.id || null
        });

        if (rpcError) {
          console.warn('[Items] RPC adjust_item_current_stock error, attempting fallback:', rpcError);
          const diff = parsedNewStock - currentStockQty;
          if (diff > 0) {
            const { data: inOrder, error: inOrderErr } = await supabase
              .from('stock_in_orders')
              .insert([{
                project_id: adjustProjectId,
                created_by: profile?.id || null,
                received_date: new Date().toISOString().split('T')[0],
                notes: `Stock balance adjusted (+${diff} ${formData.unit}) | Reason: ${stockAdjustReason.trim()}`
              }])
              .select().single();
            if (!inOrderErr && inOrder) {
              await supabase.from('stock_in_items').insert([{
                order_id: inOrder.id,
                item_id: selectedItem.id,
                quantity: diff,
                notes: `Stock balance increased | Reason: ${stockAdjustReason.trim()}`
              }]);
              await supabase.from('stock_transactions').insert([{
                project_id: adjustProjectId,
                item_id: selectedItem.id,
                quantity: diff,
                transaction_type: 'stock_in',
                notes: `Stock balance increased (+${diff} ${formData.unit}) | Reason: ${stockAdjustReason.trim()}`,
                created_by: profile?.id || null
              }]);
            }
          } else if (diff < 0) {
            await supabase.from('stock_transactions').insert([{
              project_id: adjustProjectId,
              item_id: selectedItem.id,
              quantity: Math.abs(diff),
              transaction_type: 'stock_out',
              notes: `Stock balance decreased (-${Math.abs(diff)} ${formData.unit}) | Reason: ${stockAdjustReason.trim()}`,
              created_by: profile?.id || null
            }]);
          }

          // Insert audit log
          await supabase.from('stock_adjustment_logs').insert([{
            item_id: selectedItem.id,
            project_id: adjustProjectId,
            previous_quantity: currentStockQty,
            new_quantity: parsedNewStock,
            difference: diff,
            reason: stockAdjustReason.trim(),
            created_by: profile?.id || null
          }]);
        }
        toast.success(rpcData?.message || t('items.toasts.stockAdjustedSuccess', { current: currentStockQty, newQty: parsedNewStock, unit: formData.unit }));
      } else {
        toast.success(t('items.toasts.itemUpdatedSuccess'));
      }

      setIsEditOpen(false);
      fetchItems();
    } catch (error) {
      console.error('[Items] Update error:', error);
      const code = error?.code;
      if (code === '23505') {
        const detail = error?.details || '';
        if (detail.includes('sku')) {
          toast.error(t('items.toasts.skuExists'));
        } else {
          toast.error(t('items.toasts.duplicateEntry') + ': ' + (error?.message || ''));
        }
      } else if (code === '23503') {
        toast.error(t('items.toasts.categoryNotFound'));
      } else if (code === '23502') {
        toast.error(t('items.toasts.requiredFields'));
      } else if (code === '23514') {
        toast.error(t('items.toasts.validationFailed') + ': ' + (error?.message || ''));
      } else if (error?.status === 403 || code === '42501') {
        toast.error(t('items.toasts.noEditPermission'));
      } else if (error?.message) {
        toast.error(t('common.error') + ': ' + error.message);
      } else {
        toast.error(t('items.toasts.saveUnexpectedError'));
      }
    } finally {
      setIsAdjustingStock(false);
    }
  };

  const handleDeleteItem = async (force = false) => {
    if (!selectedItem || isDeleting) return;
    if (!allowItemDeletion) {
      toast.error(t('items.toasts.itemDeletionDisabled'));
      return;
    }
    setIsDeleting(true);
    try {
      if (force || hasTransactionConflict) {
        // Attempt atomic force delete RPC (Migration 92 / 48)
        const { data, error: rpcError } = await supabase.rpc('admin_force_delete_item', {
          p_item_id: selectedItem.id
        });

        if (rpcError) {
          throw rpcError;
        }

        toast.success(data?.message || t('items.toasts.forceDeletedSuccess'));
        setIsDeleteOpen(false);
        setHasTransactionConflict(false);
        fetchItems();
        return;
      }

      // Standard delete
      const { error } = await supabase
        .from('items')
        .delete()
        .eq('id', selectedItem.id);

      if (error) {
        if (error.code === '23503') {
          // Foreign key violation: switch dialog to Force Delete mode
          setHasTransactionConflict(true);
          return;
        }
        throw error;
      }

      toast.success(t('items.toasts.itemDeletedSuccess'));
      setIsDeleteOpen(false);
      setHasTransactionConflict(false);
      fetchItems();
    } catch (error) {
      console.error('Delete Item Error:', error);

      if (isSchemaMismatchError(error)) {
        toast.error(t('items.toasts.forceDeleteSchemaMismatch'));
      } else if (error?.status === 403 || error?.code === '42501' || String(error?.message).includes('Unauthorized')) {
        toast.error(t('items.toasts.requiresDeletePermission'));
      } else if (error?.code === '23503') {
        toast.error(t('items.toasts.cannotDeleteHasReference'));
      } else if (error?.code === 'PGRST202' || error?.status === 404) {
        toast.error(t('items.toasts.forceDeleteRpcMissing'));
      } else {
        const cleanMsg = cleanRpcMessage(error);
        toast.error(cleanMsg ? `${t('items.toasts.deleteItemError')}: ${cleanMsg}` : t('items.toasts.deleteItemError'));
      }
    } finally {
      setIsDeleting(false);
    }
  };

  const openEditDialog = (item) => {
    if (!can('items.update')) {
      toast.error(t('items.toasts.requiresEditPermission'));
      return;
    }
    setSelectedItem(item);
    setFormData({ 
      name: item.name, 
      model: item.model !== '-' ? (item.model || '') : '',
      sku: item.sku !== '-' ? (item.sku || '') : '', 
      source: item.source !== '-' ? (item.source || '') : '',
      vendor: item.vendor !== '-' ? (item.vendor || '') : '',
      category_id: item.category_id || '',
      unit: item.unit || 'ชิ้น', 
      description: item.description || item.notes || '',
      image_url: item.image_url || ''
    });

    // Initialize stock adjustment states
    const targetProjId = item.project_id || (projectsList[0]?.id || '');
    setAdjustProjectId(targetProjId);

    let currentQty = 0;
    if (item.balance !== undefined && item.project_id === targetProjId) {
      currentQty = item.balance;
    } else {
      const foundBalance = rawStockBalances.find(b => b.item_id === item.id && b.project_id === targetProjId);
      currentQty = foundBalance && foundBalance.balance !== undefined ? foundBalance.balance : 0;
    }
    setCurrentStockQty(currentQty);
    setNewStockQty(String(currentQty));
    setStockAdjustReason('');
    setIsEditOpen(true);
  };

  const openDeleteDialog = (item) => {
    if (!can('items.delete')) {
      toast.error(t('items.toasts.requiresDeletePermission'));
      return;
    }
    setSelectedItem(item);
    setHasTransactionConflict(false);
    setIsDeleteOpen(true);
  };

  const openTransferDialog = (item) => {
    if (!canTransferInventory) {
      toast.error(t('items.toasts.requiresTransferPermission'));
      return;
    }
    setItemToTransfer(item);
    setIsTransferOpen(true);
  };

  // Interactive Column Sorting Handler
  const handleSort = (key) => {
    setSortConfig(prev => {
      if (prev.key === key) {
        return { key, direction: prev.direction === 'asc' ? 'desc' : 'asc' };
      }
      return { key, direction: 'asc' };
    });
  };

  // Expand / Collapse group handlers
  const toggleGroupCollapse = (groupKey) => {
    setCollapsedGroupKeys(prev => {
      const next = new Set(prev);
      if (next.has(groupKey)) {
        next.delete(groupKey);
      } else {
        next.add(groupKey);
      }
      return next;
    });
  };

  // Build hierarchical groups
  const hierarchicalGroups = useMemo(() => {
    const childRecords = [];
    const parentRecords = [];

    items.forEach(r => {
      const isChild = r.item_type === 'CHILD' || Boolean(r.parent_sku) || Boolean(r.parent_id);
      if (isChild) {
        childRecords.push(r);
      } else {
        parentRecords.push(r);
      }
    });

    const parentMapBySku = new Map();
    const parentMapById = new Map();

    const groups = parentRecords.map(p => {
      const group = {
        key: p.recordKey,
        parent: p,
        children: []
      };
      if (p.sku && p.sku !== '-') {
        const normSku = p.sku.trim().toLowerCase();
        if (!parentMapBySku.has(normSku)) {
          parentMapBySku.set(normSku, []);
        }
        parentMapBySku.get(normSku).push(group);
      }
      if (p.id) {
        if (!parentMapById.has(p.id)) {
          parentMapById.set(p.id, []);
        }
        parentMapById.get(p.id).push(group);
      }
      return group;
    });

    const orphanGroups = [];
    childRecords.forEach(c => {
      let matchedGroup = null;
      const pSku = c.parent_sku ? c.parent_sku.trim().toLowerCase() : null;

      if (pSku && parentMapBySku.has(pSku)) {
        const candidates = parentMapBySku.get(pSku);
        matchedGroup = candidates.find(g => g.parent.project_id === c.project_id) || candidates[0];
      } else if (c.parent_id && parentMapById.has(c.parent_id)) {
        const candidates = parentMapById.get(c.parent_id);
        matchedGroup = candidates.find(g => g.parent.project_id === c.project_id) || candidates[0];
      }

      if (matchedGroup) {
        // Prevent accidental duplicate child entries
        if (!matchedGroup.children.some(existing => existing.recordKey === c.recordKey)) {
          matchedGroup.children.push(c);
        }
      } else {
        orphanGroups.push({
          key: c.recordKey,
          parent: { ...c, isOrphanChild: true },
          children: []
        });
      }
    });

    return [...groups, ...orphanGroups];
  }, [items]);

  // Filter groups according to search, category, and project
  const filteredGroups = useMemo(() => {
    const q = searchQuery.toLowerCase().trim();

    const matchesItemSearch = (item) => {
      if (!q) return true;
      return (
        (item.name && item.name.toLowerCase().includes(q)) ||
        (item.model && item.model.toLowerCase().includes(q)) ||
        (item.sku && item.sku.toLowerCase().includes(q)) ||
        (item.source && item.source.toLowerCase().includes(q)) ||
        (item.vendor && item.vendor.toLowerCase().includes(q)) ||
        (item.description && item.description.toLowerCase().includes(q)) ||
        (item.project_display && item.project_display.toLowerCase().includes(q)) ||
        (item.category_name && item.category_name.toLowerCase().includes(q))
      );
    };

    const matchesItemCategory = (item) => {
      return categoryFilter === 'all' || item.category_id === categoryFilter;
    };

    const matchesItemProject = (item) => {
      if (projectFilter === 'all') return true;
      if (projectFilter === 'none') return !item.project_id;
      return item.project_id === projectFilter;
    };

    return hierarchicalGroups.reduce((acc, group) => {
      const parentMatchesProj = matchesItemProject(group.parent);
      const parentMatchesCat = matchesItemCategory(group.parent);
      const parentMatchesSearch = matchesItemSearch(group.parent);

      // Filter children by project and category
      const validChildren = group.children.filter(c => {
        return matchesItemProject(c) && (categoryFilter === 'all' || matchesItemCategory(c));
      });

      const hasChildMatchingSearch = validChildren.some(c => matchesItemSearch(c));

      // Case 1: Parent matches project & category & search -> include parent and its valid children
      if (parentMatchesProj && parentMatchesCat && parentMatchesSearch) {
        acc.push({
          ...group,
          children: validChildren
        });
      }
      // Case 2: Parent doesn't match search text directly, but a child does -> keep parent as context + matching children
      else if ((parentMatchesProj || validChildren.length > 0) && hasChildMatchingSearch) {
        acc.push({
          ...group,
          children: q ? validChildren.filter(c => matchesItemSearch(c)) : validChildren
        });
      }

      return acc;
    }, []);
  }, [hierarchicalGroups, searchQuery, categoryFilter, projectFilter]);

  // Sort groups (Preserves parent-child hierarchy by sorting at root/parent level)
  const sortedGroups = useMemo(() => {
    return [...filteredGroups].sort((groupA, groupB) => {
      const pA = groupA.parent;
      const pB = groupB.parent;
      let valA, valB;

      switch (sortConfig.key) {
        case 'name':
          valA = pA.name || '';
          valB = pB.name || '';
          break;
        case 'model':
          valA = pA.model || '';
          valB = pB.model || '';
          break;
        case 'source':
          valA = pA.source || '';
          valB = pB.source || '';
          break;
        case 'vendor':
          valA = pA.vendor || '';
          valB = pB.vendor || '';
          break;
        case 'project_display':
          valA = pA.project_location || pA.project_display || '';
          valB = pB.project_location || pB.project_display || '';
          break;
        case 'category_name':
          valA = pA.category_name || '';
          valB = pB.category_name || '';
          break;
        case 'balance':
          valA = Number(pA.balance) || 0;
          valB = Number(pB.balance) || 0;
          break;
        default:
          valA = pA.name || '';
          valB = pB.name || '';
      }

      let comp = 0;
      if (typeof valA === 'number' && typeof valB === 'number') {
        comp = valA - valB;
      } else {
        comp = String(valA).localeCompare(String(valB), 'th', { numeric: true, sensitivity: 'base' });
      }

      return sortConfig.direction === 'asc' ? comp : -comp;
    });
  }, [filteredGroups, sortConfig]);

  // Pagination calculations based on Parent Groups
  const totalRootGroups = sortedGroups.length;
  const totalFilteredRecords = useMemo(() => {
    return sortedGroups.reduce((sum, g) => sum + 1 + g.children.length, 0);
  }, [sortedGroups]);

  const totalPages = Math.max(1, Math.ceil(totalRootGroups / rowsPerPage));
  const startIndex = (currentPage - 1) * rowsPerPage;
  const endIndex = Math.min(startIndex + rowsPerPage, totalRootGroups);
  const paginatedGroups = sortedGroups.slice(startIndex, endIndex);

  // Flatten active page groups into display rows for rendering
  const paginatedItems = useMemo(() => {
    const rows = [];
    paginatedGroups.forEach(group => {
      const isCollapsed = collapsedGroupKeys.has(group.key);
      const hasChildren = group.children.length > 0;

      // Add parent row
      rows.push({
        ...group.parent,
        isParentRow: true,
        isChildRow: false,
        hasChildren: hasChildren,
        childCount: group.children.length,
        isCollapsed: isCollapsed,
        groupKey: group.key,
      });

      // Add children if not collapsed
      if (hasChildren && !isCollapsed) {
        const sortedChildren = [...group.children].sort((cA, cB) => {
          if (cA.seq_no && cB.seq_no && cA.seq_no !== cB.seq_no) {
            return cA.seq_no - cB.seq_no;
          }
          return (cA.name || '').localeCompare(cB.name || '', 'th', { numeric: true });
        });

        sortedChildren.forEach((child, idx) => {
          rows.push({
            ...child,
            isParentRow: false,
            isChildRow: true,
            parentName: group.parent.name,
            parentSku: group.parent.sku,
            parentModel: group.parent.model,
            isLastChild: idx === sortedChildren.length - 1,
            groupKey: group.key,
          });
        });
      }
    });
    return rows;
  }, [paginatedGroups, collapsedGroupKeys]);

  const expandAllGroups = () => setCollapsedGroupKeys(new Set());
  const collapseAllGroups = () => {
    const allKeys = new Set(filteredGroups.filter(g => g.children.length > 0).map(g => g.key));
    setCollapsedGroupKeys(allKeys);
  };

  useEffect(() => {
    setCurrentPage(1);
    setPageInput('1');
  }, [searchQuery, categoryFilter, projectFilter, rowsPerPage]);

  useEffect(() => {
    if (currentPage > totalPages) {
      setCurrentPage(totalPages);
      setPageInput(String(totalPages));
    }
  }, [totalPages, currentPage]);

  const handlePageInputChange = (e) => {
    const val = e.target.value;
    setPageInput(val);
    const num = parseInt(val, 10);
    if (!isNaN(num) && num >= 1 && num <= totalPages) {
      setCurrentPage(num);
    }
  };

  const handlePageInputBlur = () => {
    const num = parseInt(pageInput, 10);
    if (isNaN(num) || num < 1) {
      setCurrentPage(1);
      setPageInput('1');
    } else if (num > totalPages) {
      setCurrentPage(totalPages);
      setPageInput(String(totalPages));
    } else {
      setCurrentPage(num);
      setPageInput(String(num));
    }
  };

  // Master KPI Summary Calculations
  const uniqueMasterItemsCount = new Set(items.map(i => i.id)).size;
  const parentKitsCount = useMemo(() => new Set(items.filter(i => i.item_type !== 'CHILD' && !i.parent_sku).map(i => i.id)).size, [items]);
  const childKitsCount = useMemo(() => new Set(items.filter(i => i.item_type === 'CHILD' || Boolean(i.parent_sku)).map(i => i.id)).size, [items]);
  const totalStockQuantity = items.reduce((acc, i) => acc + (parseInt(i.balance, 10) || 0), 0);
  const totalCategoriesCount = categories.length;
  const activeLocationsWithStockCount = new Set(items.filter(i => i.balance > 0 && i.project_id).map(i => i.project_id)).size;

  // Sort Icon Renderer
  const renderSortIcon = (key) => {
    if (sortConfig.key !== key) {
      return <ArrowUpDown className="w-3 h-3 text-muted-foreground/40 shrink-0" />;
    }
    return sortConfig.direction === 'asc' ? (
      <ArrowUp className="w-3.5 h-3.5 text-primary shrink-0" />
    ) : (
      <ArrowDown className="w-3.5 h-3.5 text-primary shrink-0" />
    );
  };

  // Source Badge Renderer (Local: Sky / MapPin, Import: Amber / Plane)
  const renderSourceBadge = (source) => {
    const src = (source || '').trim().toLowerCase();
    if (src === 'local') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium bg-sky-500/10 text-sky-700 dark:text-sky-300 border border-sky-500/20">
          <MapPin className="w-3 h-3 shrink-0" />
          <span className="hidden sm:inline">{t('items.table.local')}</span>
          <span className="sm:hidden">L</span>
        </span>
      );
    }
    if (src === 'import') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium bg-amber-500/10 text-amber-700 dark:text-amber-300 border border-amber-500/20">
          <Plane className="w-3 h-3 shrink-0" />
          <span className="hidden sm:inline">{t('items.table.import')}</span>
          <span className="sm:hidden">I</span>
        </span>
      );
    }
    if (source && source.trim() !== '-' && source.trim() !== '') {
      return (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-medium bg-muted text-muted-foreground border border-border">
          <span>{source}</span>
        </span>
      );
    }
    return <span className="text-muted-foreground/50">-</span>;
  };

  // Vendor Pill Renderer (Muted pill matching Model column, truncated with tooltip)
  const renderVendorCell = (vendor) => {
    if (!vendor || vendor.trim() === '-' || vendor.trim() === '') {
      return <span className="text-muted-foreground/50">-</span>;
    }
    return (
      <span 
        className="inline-block max-w-[180px] px-2 py-0.5 rounded bg-muted/60 font-mono text-[11px] text-foreground font-medium truncate line-clamp-1"
        title={vendor}
      >
        {vendor}
      </span>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in-50 duration-200">
      {/* Top Banner Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-600 dark:text-indigo-400">
              <Package className="w-7 h-7" />
            </div>
            <span>{t('items.title')}</span>
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            {t('items.subtitle')}
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => fetchItems(false)}
            disabled={loading || refreshing}
            className="rounded-lg h-9 px-3 gap-1.5 border-input hover:bg-accent text-xs font-medium cursor-pointer shadow-xs"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${(loading || refreshing) ? 'animate-spin text-indigo-600' : ''}`} />
            <span>{refreshing ? t('common.pleaseWait') : t('common.refresh')}</span>
          </Button>
        </div>
      </div>

      {/* KPI Stats Bar */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 sm:gap-4">
        <Card className="p-4 rounded-xl bg-card border border-border shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-muted-foreground">{t('items.kpis.totalMasterItems')}</span>
            <div className="p-2 rounded-lg bg-indigo-500/10 text-indigo-600 dark:text-indigo-400">
              <Box className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-xl font-bold tracking-tight">{uniqueMasterItemsCount}</span>
            <span className="text-xs text-muted-foreground font-medium">{t('items.kpis.itemsUnit')}</span>
          </div>
          <div className="mt-1 text-[11px] text-muted-foreground font-mono">
            {parentKitsCount} {t('items.kpis.parents')} • {childKitsCount} {t('items.kpis.children')}
          </div>
        </Card>

        <Card className="p-4 rounded-xl bg-card border border-border shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-muted-foreground">{t('items.kpis.totalStockBalance')}</span>
            <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
              <CheckCircle2 className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-xl font-bold tracking-tight text-emerald-600 dark:text-emerald-400">
              {totalStockQuantity.toLocaleString()}
            </span>
            <span className="text-xs text-muted-foreground font-medium">{t('items.kpis.units')}</span>
          </div>
        </Card>

        <Card className="p-4 rounded-xl bg-card border border-border shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-muted-foreground">{t('items.kpis.activeLocations')}</span>
            <div className="p-2 rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
              <Building2 className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-xl font-bold tracking-tight">{activeLocationsWithStockCount}</span>
            <span className="text-xs text-muted-foreground font-medium">{t('items.kpis.locationsUnit')}</span>
          </div>
        </Card>

        <Card className="p-4 rounded-xl bg-card border border-border shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs font-semibold text-muted-foreground">{t('items.kpis.categories')}</span>
            <div className="p-2 rounded-lg bg-violet-500/10 text-violet-600 dark:text-violet-400">
              <Tag className="w-4 h-4" />
            </div>
          </div>
          <div className="mt-2 flex items-baseline gap-2">
            <span className="text-xl font-bold tracking-tight">{totalCategoriesCount}</span>
            <span className="text-xs text-muted-foreground font-medium">{t('items.kpis.categoriesUnit')}</span>
          </div>
        </Card>
      </div>

      {/* Filter, Search & Layout Control Toolbar */}
      <Card className="p-4 rounded-xl bg-card border border-border shadow-xs space-y-3">
        <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-3">
          {/* Search Box */}
          <div className="relative flex-1 min-w-[240px]">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              type="search"
              aria-label={t('items.filters.searchPlaceholder')}
              placeholder={t('items.filters.searchPlaceholder')}
              className="pl-9 pr-4 h-9 rounded-lg text-base sm:text-xs bg-background border-input shadow-xs"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          {/* Filter Dropdowns */}
          <div className="flex flex-wrap items-center gap-2">
            {/* Category Filter */}
            <div className="flex items-center gap-1.5 min-w-[150px] flex-1 sm:flex-initial">
              <Tag className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
              <select
                className="h-9 w-full rounded-lg border border-input bg-background px-3 py-1 text-xs font-medium focus:ring-2 focus:ring-primary transition-colors cursor-pointer shadow-xs"
                value={categoryFilter}
                onChange={(e) => setCategoryFilter(e.target.value)}
              >
                <option value="all">{t('items.filters.allCategoriesCount', { count: categories.length })}</option>
                {categories.map(c => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>

            {/* Project & Storage Location Filter */}
            <div className="min-w-[260px] flex-1 sm:flex-initial">
              <ProjectLocationSelector
                projects={projectsList}
                value={projectFilter}
                onChange={(val) => setProjectFilter(val)}
                allowAll={true}
                allLabel={t('items.filters.allProjectsLocations')}
                mode="unified"
                size="sm"
                showSummaryCard={false}
              />
            </div>

            {/* View Mode Switcher */}
            <div className="flex items-center bg-muted/50 p-0.5 rounded-lg border border-border shrink-0">
              <Button
                type="button"
                variant={viewMode === 'table' ? 'default' : 'ghost'}
                size="sm"
                onClick={() => setViewMode('table')}
                className={`h-9 sm:h-8 px-3 sm:px-2.5 rounded-md text-xs gap-1 font-medium cursor-pointer ${viewMode === 'table' ? 'bg-background text-foreground shadow-xs' : 'text-muted-foreground hover:text-foreground'}`}
