                      <span className="px-1.5 py-0.5 rounded text-[10px] font-mono font-bold bg-blue-500/10 text-blue-600 border border-blue-500/20 flex items-center gap-1">
                        <CornerDownRight className="w-3 h-3" />
                        {t('items.table.child')} ({t('items.table.parentLabel')} {item.parentSku || item.parentName})
                      </span>
                    ) : item.hasChildren ? (
                      <span className="px-1.5 py-0.5 rounded text-[10px] font-mono font-bold bg-indigo-500/10 text-indigo-700 dark:text-indigo-300 border border-indigo-500/25 flex items-center gap-1">
                        <FolderTree className="w-3 h-3" />
                        {t('items.table.parentWithChildren', { count: item.childCount })}
                      </span>
                    ) : null}
                  </div>

                  {/* Image & Title Header */}
                  <div className="flex items-start gap-3">
                    {item.image_url ? (
                      <img src={item.image_url} alt={item.name} className="w-12 h-12 object-cover rounded-lg border border-border shadow-xs shrink-0" />
                    ) : (
                      <div className="w-12 h-12 bg-muted/60 rounded-lg flex items-center justify-center border border-border/60 text-muted-foreground/60 shrink-0">
                        <ImageIcon className="w-5 h-5" />
                      </div>
                    )}

                    <div className="min-w-0 flex-1">
                      <h4 className="font-bold text-sm text-foreground line-clamp-2 leading-tight">
                        {item.name}
                      </h4>
                      <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground font-mono">
                        {item.model && item.model !== '-' && <span>{t('items.table.model')}: {item.model}</span>}
                        {item.sku && item.sku !== '-' && <span>SKU: {item.sku}</span>}
                      </div>
                    </div>
                  </div>

                  {/* Storage Location / Warehouse Pill */}
                  <div className="mt-3 p-2.5 rounded-lg bg-muted/40 border border-border/60 text-xs">
                    {item.project_location ? (
                      <div className="font-bold text-emerald-700 dark:text-emerald-300 flex items-center gap-1.5 truncate">
                        <Building2 className="w-3.5 h-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />
                        <span className="truncate">{item.project_location}</span>
                      </div>
                    ) : (
                      <div className="text-muted-foreground/50 italic text-[11px] flex items-center gap-1.5">
                        <Building2 className="w-3.5 h-3.5 shrink-0 opacity-40" />
                        <span>{t('items.table.noLocation')}</span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Card Footer: Stock Balance & Actions */}
                <div className="pt-2 border-t border-border/40 flex items-center justify-between gap-2">
                  <div className="flex items-baseline gap-1.5">
                    <span className="text-xs text-muted-foreground">{t('items.table.stock')}</span>
                    <span className={`px-2 py-0.5 rounded-md text-xs font-bold font-mono ${
                      item.balance > 0 
                        ? 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border border-emerald-500/30' 
                        : 'bg-muted text-muted-foreground border border-border'
                    }`}>
                      {item.balance} {item.unit}
                    </span>
                  </div>

                  <div className="flex items-center gap-1">
                    <Button 
                      variant="ghost" 
                      size="icon" 
                      className="h-9 w-9 sm:h-7 sm:w-7 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg text-amber-600 hover:bg-amber-50"
                      onClick={() => openAdjustmentHistoryDialog(item)}
                      title={t('items.table.stockHistoryTitle')}
                    >
                      <History className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
                    </Button>
                    {canTransferInventory && (
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-9 w-9 sm:h-7 sm:w-7 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-950/40 disabled:opacity-30 disabled:cursor-not-allowed"
                        onClick={() => openTransferDialog(item)}
                        disabled={!item.project_id || (parseInt(item.balance, 10) || 0) <= 0}
                        title={
                          !item.project_id || (parseInt(item.balance, 10) || 0) <= 0 
                            ? t('items.table.cannotTransferNoStock') 
                            : t('items.table.transferLocationTitle')
                        }
                      >
                        <ArrowRightLeft className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
                      </Button>
                    )}
                    {can('items.update') && (
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-9 w-9 sm:h-7 sm:w-7 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg text-blue-600 hover:bg-blue-50"
                        onClick={() => openEditDialog(item)}
                        title={t('items.table.editMasterItem')}
                      >
                        <Edit3 className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
                      </Button>
                    )}
                    {can('items.delete') && allowItemDeletion && (
                      <Button 
                        variant="ghost" 
                        size="icon" 
                        className="h-9 w-9 sm:h-7 sm:w-7 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg text-red-500 hover:bg-red-50"
                        onClick={() => openDeleteDialog(item.originalItem || item)}
                        title={t('items.table.deleteItem')}
                      >
                        <Trash2 className="w-4 h-4 sm:w-3.5 sm:h-3.5" />
                      </Button>
                    )}
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Supabase-Style Compact Pagination Footer Bar */}
      {totalRootGroups > 0 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-4 py-3 bg-card rounded-xl border border-border shadow-xs text-xs text-muted-foreground select-none">
          {/* Left Controls: Navigation & Page Input */}
          <div className="flex items-center gap-2">
            {/* Previous Page Button */}
            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={currentPage <= 1}
              onClick={() => {
                const p = Math.max(1, currentPage - 1);
                setCurrentPage(p);
                setPageInput(String(p));
              }}
              className="h-9 w-9 sm:h-8 sm:w-8 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg border-border text-foreground hover:bg-accent disabled:opacity-30 transition-colors cursor-pointer shadow-xs"
              aria-label={t('items.pagination.prevPage')}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>

            {/* Page Counter & Editable Numeric Input */}
            <div className="flex items-center gap-1.5 font-medium text-foreground">
              <span>{t('items.pagination.page')}</span>
              <input
                type="number"
                min={1}
                max={totalPages}
                value={pageInput}
                onChange={handlePageInputChange}
                onBlur={handlePageInputBlur}
                onKeyDown={(e) => { if (e.key === 'Enter') handlePageInputBlur(); }}
                className="h-9 sm:h-8 w-12 text-center font-mono text-xs font-bold rounded-lg border border-input bg-background focus:ring-2 focus:ring-primary focus:outline-none transition-colors shadow-xs"
                aria-label={t('items.pagination.currentPaginationNumber')}
              />
              <span>{t('items.pagination.of')}</span>
              <span className="font-mono font-bold text-foreground">{totalPages}</span>
            </div>

            {/* Next Page Button */}
            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={currentPage >= totalPages}
              onClick={() => {
                const p = Math.min(totalPages, currentPage + 1);
                setCurrentPage(p);
                setPageInput(String(p));
              }}
              className="h-9 w-9 sm:h-8 sm:w-8 min-h-[36px] min-w-[36px] sm:min-h-0 sm:min-w-0 rounded-lg border-border text-foreground hover:bg-accent disabled:opacity-30 transition-colors cursor-pointer shadow-xs"
              aria-label={t('items.pagination.nextPage')}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>

          {/* Right Controls: Rows per Page Selector & Total Records Count */}
          <div className="flex items-center gap-3">
            {/* Rows per page selector */}
            <div className="flex items-center gap-1.5">
              <select
                value={rowsPerPage}
                onChange={(e) => {
                  setRowsPerPage(Number(e.target.value));
                }}
                className="h-9 sm:h-8 rounded-lg border border-input bg-background px-2.5 text-xs font-medium text-foreground focus:ring-2 focus:ring-primary cursor-pointer shadow-xs transition-colors"
                aria-label={t('items.pagination.rowsPerPage')}
              >
                <option value={25}>{t('items.pagination.groupsPerPage', { count: 25 })}</option>
                <option value={50}>{t('items.pagination.groupsPerPage', { count: 50 })}</option>
                <option value={100}>{t('items.pagination.groupsPerPage', { count: 100 })}</option>
                <option value={200}>{t('items.pagination.groupsPerPage', { count: 200 })}</option>
              </select>
            </div>

            {/* Total Records Counter */}
            <span className="font-mono text-xs text-muted-foreground font-medium">
              {t('items.pagination.groupsAndItemsCount', { groups: totalRootGroups.toLocaleString(), items: totalFilteredRecords.toLocaleString() })}
            </span>
          </div>
        </div>
      )}

      {/* Edit Master Item Modal */}
      <Dialog open={isEditOpen} onOpenChange={setIsEditOpen}>
        <DialogContent className="sm:max-w-[480px] rounded-xl border-border bg-card shadow-lg">
          <form onSubmit={handleEditItem}>
            <DialogHeader>
              <DialogTitle className="text-xl font-bold flex items-center gap-2">
                <Edit3 className="w-5 h-5 text-primary" />
                <span>{t('items.dialogs.editItemTitle')}</span>
              </DialogTitle>
            </DialogHeader>

            <div className="grid gap-4 py-4">
              <div className="space-y-1.5">
                <Label htmlFor="edit-name" className="text-xs font-semibold">{t('items.dialogs.itemName')} <span className="text-destructive">*</span></Label>
                <Input id="edit-name" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="rounded-lg font-medium" />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="edit-model" className="text-xs font-semibold">{t('items.dialogs.model')} <span className="text-destructive">*</span></Label>
                  <Input id="edit-model" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} placeholder={t('items.dialogs.enterModel')} className="rounded-lg" />
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="edit-sku" className="text-xs font-semibold">{t('items.dialogs.sku')}</Label>
                  <Input id="edit-sku" value={formData.sku} onChange={e => setFormData({...formData, sku: e.target.value})} className="rounded-lg font-mono" />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="edit-source" className="text-xs font-semibold">{t('items.dialogs.source')}</Label>
                  <select 
                    id="edit-source" 
                    className="flex h-9 w-full rounded-lg border border-input bg-background px-3 py-1.5 text-xs font-medium"
                    value={formData.source} 
                    onChange={e => setFormData({...formData, source: e.target.value})}
                  >
                    <option value="">{t('items.dialogs.selectSource')}</option>
                    <option value="Local">{t('items.sources.local')}</option>
                    <option value="Import">{t('items.sources.import')}</option>
                  </select>
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="edit-vendor" className="text-xs font-semibold">{t('items.dialogs.vendor')}</Label>
                  <Input 
                    id="edit-vendor" 
                    value={formData.vendor} 
                    onChange={e => setFormData({...formData, vendor: e.target.value})} 
                    placeholder={t('items.dialogs.enterVendor')} 
                    className="rounded-lg" 
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label htmlFor="edit-category" className="text-xs font-semibold">{t('items.dialogs.category')}</Label>
                  <select id="edit-category" className="flex h-9 w-full rounded-lg border border-input bg-background px-3 py-1.5 text-xs font-medium" value={formData.category_id} onChange={e => setFormData({...formData, category_id: e.target.value})}>
                    <option value="">{t('items.dialogs.selectCategory')}</option>
                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="edit-unit" className="text-xs font-semibold">{t('items.dialogs.unit')} <span className="text-destructive">*</span></Label>
                  <Input id="edit-unit" required value={formData.unit} onChange={e => setFormData({...formData, unit: e.target.value})} className="rounded-lg" />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="edit-description" className="text-xs font-semibold">{t('items.dialogs.descriptionNotes')}</Label>
                <Input id="edit-description" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="rounded-lg" />
              </div>

              <div className="space-y-1.5">
                <Label htmlFor="edit-image" className="text-xs font-semibold">{t('items.dialogs.itemImage')}</Label>
                <div className="flex items-center gap-3">
                  {formData.image_url ? (
                    <img src={formData.image_url} alt="Preview" className="w-14 h-14 object-cover rounded-lg border shadow-xs shrink-0" />
                  ) : (
                    <div className="w-14 h-14 bg-muted rounded-lg flex items-center justify-center border text-muted-foreground shrink-0">
                      <ImageIcon className="w-5 h-5" />
                    </div>
                  )}
                  <Input id="edit-image" type="file" accept="image/*" onChange={handleImageUpload} disabled={uploadingImage} className="rounded-lg text-xs" />
                </div>
              </div>

              {/* Section: Current Stock Adjustment */}
              <div className="pt-3 border-t border-border/40 space-y-3">
                <div className="flex items-center justify-between">
                  <Label className="text-xs font-bold flex items-center gap-1.5 text-foreground">
                    <SlidersHorizontal className="w-3.5 h-3.5 text-primary" />
                    <span>{t('items.dialogs.currentStockAdjustment')}</span>
                  </Label>

                  {allowDirectStockAdjustment && canAdjustStock ? (
                    <span className="text-[10px] font-bold bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border border-emerald-500/30 px-2 py-0.5 rounded-full flex items-center gap-1">
                      <Sparkles className="w-2.5 h-2.5" />
                      <span>{t('items.dialogs.enabled')}</span>
                    </span>
                  ) : (
                    <span className="text-[10px] font-bold bg-muted text-muted-foreground border border-border/40 px-2 py-0.5 rounded-full flex items-center gap-1">
                      <Lock className="w-2.5 h-2.5" />
                      <span>{t('items.dialogs.disabled')}</span>
                    </span>
                  )}
                </div>

                {!allowDirectStockAdjustment ? (
                  <div className="p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/20 text-[11px] text-amber-800 dark:text-amber-300 flex items-start gap-2">
                    <AlertCircle className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                    <div>
                      {t('items.dialogs.directAdjustmentDisabled')}
                    </div>
                  </div>
                ) : !canAdjustStock ? (
                  <div className="p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/20 text-[11px] text-amber-800 dark:text-amber-300 flex items-start gap-2">
                    <Lock className="w-4 h-4 text-amber-600 shrink-0 mt-0.5" />
                    <div>
                      {t('items.dialogs.directAdjustmentNoPermission')}
                    </div>
                  </div>
                ) : (
                  <div className="space-y-3 p-3 rounded-lg bg-primary/5 border border-primary/20">
                    {/* Project Selector for adjustment */}
                    <div className="space-y-1">
                      <Label htmlFor="adjust-project" className="text-[11px] font-semibold text-muted-foreground flex items-center gap-1">
                        <Building2 className="w-3 h-3 text-primary" />
                        <span>{t('items.dialogs.selectLocationToAdjust')}</span>
                      </Label>
                      <select
                        id="adjust-project"
                        value={adjustProjectId}
                        onChange={(e) => handleProjectChangeForAdjustment(e.target.value)}
                        className="flex h-9 w-full rounded-lg border border-input bg-background px-3 py-1.5 text-xs font-semibold text-foreground focus:ring-2 focus:ring-primary cursor-pointer"
                      >
                        {projectsList.map(p => (
                          <option key={p.id} value={p.id}>
                            {p.project_code ? `${p.project_code} — ` : ''}{p.name}{p.location ? ` (${p.location})` : ''}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Stock comparison & input */}
                    <div className="grid grid-cols-2 gap-3 items-end">
                      <div className="space-y-1">
                        <Label className="text-[11px] font-semibold text-muted-foreground">{t('items.dialogs.currentStock')}</Label>
                        <div className="h-9 px-3 rounded-lg bg-background border border-border/80 flex items-center justify-between font-mono text-xs font-bold">
                          <span className="text-foreground">{currentStockQty}</span>
                          <span className="text-muted-foreground text-[10px]">{formData.unit || 'ชิ้น'}</span>
                        </div>
                      </div>

                      <div className="space-y-1">
                        <Label htmlFor="adjust-new-qty" className="text-[11px] font-bold text-foreground flex items-center justify-between">
                          <span>{t('items.dialogs.newStock')}</span>
                          {parseInt(newStockQty, 10) !== currentStockQty && !isNaN(parseInt(newStockQty, 10)) && (
                            <span className={`text-[10px] font-mono font-extrabold px-1.5 py-0.2 rounded-md ${
                              parseInt(newStockQty, 10) > currentStockQty 
                                ? 'bg-emerald-500/20 text-emerald-700 dark:text-emerald-300' 
                                : 'bg-rose-500/20 text-rose-700 dark:text-rose-300'
                            }`}>
                              {parseInt(newStockQty, 10) > currentStockQty ? `+${parseInt(newStockQty, 10) - currentStockQty}` : `${parseInt(newStockQty, 10) - currentStockQty}`} {formData.unit}
                            </span>
                          )}
                        </Label>
                        <Input
                          id="adjust-new-qty"
                          type="number"
                          min="0"
                          value={newStockQty}
                          onChange={(e) => setNewStockQty(e.target.value)}
                          className="h-9 rounded-lg font-mono text-xs font-bold bg-background"
                          placeholder={t('items.dialogs.enterNewStock')}
                        />
                      </div>
                    </div>

                    {/* Mandatory reason when stock changes */}
                    {parseInt(newStockQty, 10) !== currentStockQty && !isNaN(parseInt(newStockQty, 10)) && (
                      <div className="space-y-1.5 pt-1 animate-in fade-in-50 duration-200">
                        <Label htmlFor="adjust-reason" className="text-[11px] font-bold text-primary flex items-center gap-1">
                          <Sparkles className="w-3 h-3 text-amber-500" />
                          <span>{t('items.dialogs.adjustmentReason')} <span className="text-destructive">*</span></span>
                        </Label>
                        <textarea
                          id="adjust-reason"
                          rows={2}
                          required
                          value={stockAdjustReason}
                          onChange={(e) => setStockAdjustReason(e.target.value)}
                          placeholder={t('items.dialogs.adjustmentReasonPlaceholder')}
                          className="w-full rounded-lg border border-input bg-background px-3 py-2 text-xs shadow-xs placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring resize-none"
                        />
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0">
              <Button type="button" variant="outline" className="rounded-lg" onClick={() => setIsEditOpen(false)}>{t('common.cancel')}</Button>
              <Button type="submit" disabled={isAdjustingStock} className="rounded-lg bg-primary hover:bg-primary/90 text-primary-foreground font-medium shadow-xs">
                {isAdjustingStock ? t('items.dialogs.saving') : t('items.dialogs.updateItemAndStock')}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Delete Master Item Modal */}
      <Dialog 
        open={isDeleteOpen} 
        onOpenChange={(open) => {
          setIsDeleteOpen(open);
          if (!open) setHasTransactionConflict(false);
        }}
      >
        <DialogContent className="sm:max-w-[450px] rounded-xl border-border bg-card shadow-lg">
          <DialogHeader>
            <DialogTitle className="text-destructive font-bold text-lg flex items-center gap-2">
              <AlertCircle className="w-5 h-5" />
              <span>{hasTransactionConflict ? t('items.dialogs.transactionHistoryFound') : t('items.dialogs.confirmDeleteItem')}</span>
            </DialogTitle>
            <DialogDescription className="pt-2 text-foreground/80 space-y-2" asChild>
              <div>
                {hasTransactionConflict ? (
                  <div className="space-y-2">
                    <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-amber-800 dark:text-amber-300 text-xs">
                      {t('items.dialogs.hasHistoryWarning', { name: selectedItem?.name, sku: selectedItem?.sku || '-' })}
                    </div>
                    <p className="text-xs text-muted-foreground">
                      {t('items.dialogs.hasHistoryDesc')}
                    </p>
                  </div>
                ) : (
                  <p className="text-xs text-muted-foreground">
                    {t('items.dialogs.standardDeleteConfirm', { name: selectedItem?.name, sku: selectedItem?.sku || '-' })}
                  </p>
                )}
              </div>
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="mt-4 gap-2 sm:gap-0">
            <Button 
              type="button" 
              variant="outline" 
              className="rounded-lg" 
              disabled={isDeleting}
              onClick={() => {
                setIsDeleteOpen(false);
                setHasTransactionConflict(false);
              }}
            >
              {t('common.cancel')}
            </Button>
            {hasTransactionConflict ? (
              <Button 
                type="button" 
                variant="destructive" 
                className="rounded-lg font-medium bg-red-600 hover:bg-red-700 text-white shadow-xs" 
                disabled={isDeleting}
                onClick={() => handleDeleteItem(true)}
              >
                {isDeleting ? t('items.dialogs.deleting') : t('items.dialogs.forceDeleteBtn')}
              </Button>
            ) : (
              <Button 
                type="button" 
                variant="destructive" 
                className="rounded-lg font-medium shadow-xs" 
                disabled={isDeleting}
                onClick={() => handleDeleteItem(false)}
              >
                {isDeleting ? t('items.dialogs.checking') : t('items.dialogs.confirmDeleteBtn')}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Item Warehouse Transfer Dialog Modal */}
      <TransferItemDialog
        open={isTransferOpen}
        onOpenChange={setIsTransferOpen}
        item={itemToTransfer}
        projectsList={projectsList}
        onSuccess={fetchItems}
        currentProfile={profile}
      />

      {/* Stock Adjustment Audit History Dialog */}
      <ItemStockHistoryDialog
        open={isHistoryDialogOpen}
        onOpenChange={setIsHistoryDialogOpen}
        selectedItem={selectedItemForHistory}
        loading={loadingHistoryLogs}
        logs={adjustmentHistoryLogs}
      />
    </div>
  );
};

export default Items;

import { useEffect, useState, useRef, useMemo, useCallback } from 'react';
import { useSearchParams } from 'react-router-dom';
import { supabase } from '@/lib/supabase';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { 
  ArrowDownToLine, Download, Upload, Plus, Trash2, Check, 
  RefreshCw, Package, Building2, FileSpreadsheet, Layers, 
  Filter, CheckCircle2, Search, X, RotateCcw, SearchX,
  ChevronLeft, ChevronRight,
  ArrowRight, 
  MapPin, SlidersHorizontal, BarChart3, CornerDownRight
} from 'lucide-react';
import { useAuth } from '@/contexts/AuthContext';
import { format } from 'date-fns';
import toast from 'react-hot-toast';
import { dispatchStockInNotification } from '@/lib/notificationDispatcher';

import { 
  parseDopaStockCsv, 
  matchLocationToWarehouseColumn, 
  filterAndAggregateWarehouseItems 
} from '@/lib/stock-in-parser';
import { ProjectLocationSelector } from '@/components/common/ProjectLocationSelector';
import { useTranslation } from '@/i18n';
import { formatI18nDate, formatI18nNumber } from '@/lib/i18n-format';
import { filterStockInOrders } from '@/lib/stockInSearch';
import { StockInOrderDetailModal } from '@/components/stockin/StockInOrderDetailModal';

const StockIn = () => {
  const { can, user } = useAuth();
  const { t } = useTranslation();
  const [searchParams, setSearchParams] = useSearchParams();

  // URL Query Sync & Search States
  const [searchInput, setSearchInput] = useState(searchParams.get('search') || '');
  const [debouncedSearch, setDebouncedSearch] = useState(searchParams.get('search') || '');
  const [warehouseFilter, setWarehouseFilter] = useState(searchParams.get('warehouse') || 'all');
  const [currentPage, setCurrentPage] = useState(
    Math.max(1, parseInt(searchParams.get('page') || '1', 10) || 1)
  );
  const [pageSize] = useState(20);
  const [totalCount, setTotalCount] = useState(0);

  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  
  // Data for Selectors & Auto-resolution
  const [projects, setProjects] = useState([]);
  const [items, setItems] = useState([]);
  
  // Create Modal State
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [formData, setFormData] = useState({ project_id: '' });
  const [lineItems, setLineItems] = useState([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  
  // Master Raw Parsed Items from CSV (to allow dynamic warehouse re-filtering anytime)
  const [rawParsedCsvItems, setRawParsedCsvItems] = useState([]);
  const [csvDetectedWarehouses, setCsvDetectedWarehouses] = useState([]);

  // File Input Ref for CSV Upload
  const fileInputRef = useRef(null);

  // Interactive CSV Preview Modal State
  const [isImportPreviewOpen, setIsImportPreviewOpen] = useState(false);
  const [previewItems, setPreviewItems] = useState([]);
  const [selectedQtySource, setSelectedQtySource] = useState('คงเหลือ');
  const [onlyPositiveFilter, setOnlyPositiveFilter] = useState(true);
  const [previewSearch, setPreviewSearch] = useState('');
  const [debouncedPreviewSearch, setDebouncedPreviewSearch] = useState('');
  const [previewProjectId, setPreviewProjectId] = useState('');
  const [importFileName, setImportFileName] = useState('');

  // Details Dialog State
  const [selectedOrder, setSelectedOrder] = useState(null);
  const [orderDetails, setOrderDetails] = useState([]);

  // 300ms debounce for search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchInput);
      setCurrentPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [searchInput]);

  // 300ms debounce for CSV preview search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedPreviewSearch(previewSearch);
    }, 300);
    return () => clearTimeout(timer);
  }, [previewSearch]);

  // Sync state to URL search params
  useEffect(() => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev);
        if (debouncedSearch.trim()) next.set('search', debouncedSearch.trim());
        else next.delete('search');

        if (warehouseFilter && warehouseFilter !== 'all') next.set('warehouse', warehouseFilter);
        else next.delete('warehouse');

        if (currentPage > 1) next.set('page', String(currentPage));
        else next.delete('page');

        return next;
      },
      { replace: true }
    );
  }, [debouncedSearch, warehouseFilter, currentPage, setSearchParams]);

  // Initial projects & items fetch (mount only)
  useEffect(() => {
    fetchMasterData();
  }, []);

  const fetchMasterData = async () => {
    try {
      const [pRes, iRes] = await Promise.all([
        supabase
          .from('projects')
          .select('id, name, project_code, location, description')
          .eq('status', 'active')
          .order('name'),
        supabase
          .from('items')
          .select('id, name, unit, sku, image_url, category_id, model, description'),
      ]);
      setProjects(pRes.data || []);
      setItems(iRes.data || []);
    } catch (err) {
      console.error('Error loading master data:', err);
    }
  };

  const fetchOrders = useCallback(async () => {
    try {
      setLoading(true);
      const targetProject = warehouseFilter !== 'all' ? warehouseFilter : null;
      const offset = (currentPage - 1) * pageSize;

      // 1. Primary: Dedicated RPC (with GIN Trigram indexes & EXISTS subqueries)
      const { data: rpcData, error: rpcError } = await supabase.rpc('search_stock_in_orders', {
        p_search: debouncedSearch.trim() || null,
        p_project_id: targetProject,
        p_limit: pageSize,
        p_offset: offset,
      });

      if (!rpcError && Array.isArray(rpcData)) {
        const formatted = rpcData.map((row) => ({
          id: row.id,
          project_id: row.project_id,
          supplier: row.supplier,
          po_number: row.po_number,
          notes: row.notes,
          received_date: row.received_date,
          created_by: row.created_by,
          created_at: row.created_at,
          matched_items_snippet: row.matched_items_snippet,
          projects: {
            id: row.project_id,
            name: row.project_name,
            project_code: row.project_code,
            location: row.project_location,
            description: row.project_description,
          },
          profiles: {
            full_name: row.received_by_name,
          },
        }));

        setOrders(formatted);
        const total = rpcData.length > 0 ? Number(rpcData[0].total_count || 0) : 0;
        setTotalCount(total);
        return;
      }

      // 2. Resilient Client Fallback: If RPC not deployed yet, query table and filter client-side
      let query = supabase
        .from('stock_in_orders')
        .select('*, projects(id, name, project_code, location, description), profiles(full_name), stock_in_items(id, name, sku, model, serial_number, part_number, items(id, name, sku, model, description))')
        .order('created_at', { ascending: false });

      if (targetProject) {
        query = query.eq('project_id', targetProject);
      }

      const { data: fallbackData, error: fallbackError } = await query.limit(200);
      if (fallbackError && fallbackError.code !== '42P01') throw fallbackError;

      const allOrders = fallbackData || [];
      const filtered = filterStockInOrders(allOrders, {
        search: debouncedSearch,
        projectId: targetProject,
      });

      setTotalCount(filtered.length);
      setOrders(filtered.slice(offset, offset + pageSize));
    } catch (error) {
      console.error('fetchOrders error:', error);
    } finally {
      setLoading(false);
    }
  }, [debouncedSearch, warehouseFilter, currentPage, pageSize]);

  // Fetch orders on filter / search / pagination changes
  useEffect(() => {
    fetchOrders();
  }, [fetchOrders]);

  const fetchData = async () => {
    await Promise.all([fetchMasterData(), fetchOrders()]);
  };

  const handleClearSearch = () => {
    setSearchInput('');
    setDebouncedSearch('');
    setCurrentPage(1);
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setDebouncedSearch('');
    setWarehouseFilter('all');
    setCurrentPage(1);
  };

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize));

  const handleOpenCreateDialog = () => {
    const defaultProjId = projects[0]?.id || '';
    setFormData({ project_id: defaultProjId });
    setLineItems([createEmptyRow()]);
    setIsCreateDialogOpen(true);
  };

  const createEmptyRow = (item_type = 'PARENT', parent_sku = '') => ({
    tempId: Date.now() + Math.random(),
    no: null,
    item_type: item_type,
    sku: '',
    parent_sku: parent_sku,
    name: '',
    model: '',
    quantity: 1,
    serial_number: '',
    part_number: '',
    notes: ''
  });

  const handleAddLineItem = (item_type = 'PARENT', parent_sku = '') => {
    setLineItems(prev => [...prev, createEmptyRow(item_type, parent_sku)]);
  };

  const handleRemoveLineItem = (tempId) => {
    setLineItems(prev => prev.filter(item => item.tempId !== tempId));
  };

  const handleUpdateLineItem = (tempId, field, value) => {
    setLineItems(prev => prev.map(row => {
      if (row.tempId !== tempId) return row;
      if (field === 'quantity') {
        const parsed = parseInt(value, 10);
        return { ...row, quantity: isNaN(parsed) ? '' : parsed };
      }
      return { ...row, [field]: value };
    }));
  };

  // Download CSV Template with DOPA+USO Standard Format (UTF-8 BOM \uFEFF)
  const handleDownloadCsvTemplate = () => {
    const bom = '\uFEFF';
    const csvContent = bom + 
      `ลำดับ,Part No.,,รายการ,รุ่น/ยี่ห้อ,คลัง Factory C,คลัง EMS (SAP),เบิกใช้งาน,คงเหลือ,หมายเหตุ\n` +
      `1,,PARENT,ตู้ชุดDMO-GW+ขาตั้ง (ตั้งนอกอาคาร), -,7,,,7,ส่งมอบกรมการปกครอง DMO\n` +
      `,,CHILD,    - Support ขายึด SC-489 (2ชุด/1ตู้), -,3,,,3,\n` +
      `,,CHILD,    - Lightning_arrestor NF-NF,Comsolution,5,,,5,\n` +
      `1,30207-0024-04412,,สายอากาศ SC-488-HF1LDF(D00),Sinclar/Base,,6,,6,\n` +
      `2,30207-0024-01779,,สายอากาศ Yagi 406-SF1SNF (ABK),Sinclar/Fixed,10,5,,15,\n` +
      `3,30207-0024-01903,,CellFlex cable 1/2" (500m.),Comsolution,2317,1000,,3317,2317 อยู่โรงสีรอขอย้ายเข้า EMS\n`;

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'DOPA_USO_Equipment_Template.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    toast.success(t('common.success'));
  };

  // Direct CSV File Parsing with Native DOPA+USO & Multi-Warehouse Detection
  const handleCsvFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setImportFileName(file.name);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result;
        if (typeof text !== 'string') return;

        const { items: parsed, detectedWarehouses } = parseDopaStockCsv(text);
        
        if (parsed.length === 0) {
          toast.error(t('stockIn.csvImport.noItemsMatch'));
          return;
        }

        setRawParsedCsvItems(parsed);
        setCsvDetectedWarehouses(detectedWarehouses);

        const initialProjectId = formData.project_id || projects[0]?.id || '';
        setPreviewProjectId(initialProjectId);

        // Auto-match warehouse from initial selected project location
        const targetProj = projects.find(p => p.id === initialProjectId);
        const matchedWh = targetProj ? matchLocationToWarehouseColumn(targetProj.location, detectedWarehouses) : null;
        const initialSource = matchedWh || 'คงเหลือ';

        setSelectedQtySource(initialSource);
        setOnlyPositiveFilter(true);

        const aggregated = filterAndAggregateWarehouseItems(parsed, initialSource, { filterZeroQty: true });
        setPreviewItems(aggregated);
        setPreviewSearch('');
        setIsImportPreviewOpen(true);
        toast.success(t('stockIn.toasts.csvParsed', { count: parsed.length }));
      } catch (err) {
        console.error('CSV Parsing error:', err);
        toast.error(t('stockIn.toasts.csvParseError'));
      } finally {
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file, 'UTF-8');
  };

  // Handle Project Location change in Preview Modal -> Auto match warehouse & aggregate balance
  const handlePreviewProjectChange = (newProjId) => {
    setPreviewProjectId(newProjId);
    const targetProj = projects.find(p => p.id === newProjId);
    if (!targetProj || rawParsedCsvItems.length === 0) return;

    const matchedWh = matchLocationToWarehouseColumn(targetProj.location, csvDetectedWarehouses);
    if (matchedWh) {
      setSelectedQtySource(matchedWh);
      const aggregated = filterAndAggregateWarehouseItems(rawParsedCsvItems, matchedWh, { filterZeroQty: onlyPositiveFilter });
      setPreviewItems(aggregated);
      toast.success(`Filtered by [${targetProj.location}]: ${aggregated.length} item(s) found`);
    }
  };

  // Handle Manual Switch of quantity source in preview (e.g. 'คงเหลือ' vs 'คลัง Factory C' vs 'คลัง EMS')
  const handleChangeQtySource = (sourceName, filterZero = onlyPositiveFilter) => {
    setSelectedQtySource(sourceName);
    if (rawParsedCsvItems.length > 0) {
      const aggregated = filterAndAggregateWarehouseItems(rawParsedCsvItems, sourceName, { filterZeroQty: filterZero });
      setPreviewItems(aggregated);
    }
  };

  // Toggle filter for only positive balance
  const handleToggleOnlyPositive = () => {
    const nextVal = !onlyPositiveFilter;
    setOnlyPositiveFilter(nextVal);
    handleChangeQtySource(selectedQtySource, nextVal);
  };

  // Handle Project Location change in Direct Creation Modal -> Auto re-filter lineItems if CSV data is present
  const handleDirectProjectChange = (newProjId) => {
    setFormData(prev => ({ ...prev, project_id: newProjId }));
    
    if (rawParsedCsvItems.length > 0) {
      const targetProj = projects.find(p => p.id === newProjId);
      if (targetProj) {
        const matchedWh = matchLocationToWarehouseColumn(targetProj.location, csvDetectedWarehouses);
        if (matchedWh) {
          const aggregated = filterAndAggregateWarehouseItems(rawParsedCsvItems, matchedWh, { filterZeroQty: true });
          if (aggregated.length > 0) {
            setLineItems(aggregated);
            toast.success(`Updated items for [${targetProj.location}]: ${aggregated.length} item(s)`);
          }
        }
      }
    }
  };

  // Apply preview items to form
  const handleApplyPreviewToForm = () => {
    if (previewItems.length === 0) return;
    setLineItems(previewItems);
    setFormData(prev => ({ ...prev, project_id: previewProjectId || prev.project_id || projects[0]?.id || '' }));
    setIsImportPreviewOpen(false);
    setIsCreateDialogOpen(true);
    toast.success(`Loaded ${previewItems.length} item(s) into the form`);
  };

  // Direct Submit from Preview Dialog
  const handleDirectSubmitFromPreview = async () => {
    if (!previewProjectId) {
      return toast.error('Please select a storage location before recording stock receipt');
    }
    if (previewItems.length === 0) {
      return toast.error('No items available to record stock receipt');
    }

    setFormData(prev => ({ ...prev, project_id: previewProjectId }));
    setLineItems(previewItems);
    await executeStockInSubmission(previewProjectId, previewItems);
    setIsImportPreviewOpen(false);
  };

  // Execute Stock In Submission Core
  const executeStockInSubmission = async (projectId, itemsToSubmit) => {
    if (!projectId) {
      return toast.error('Please select a storage location before recording stock receipt');
    }

    if (itemsToSubmit.length === 0) {
      return toast.error('Please add at least 1 item for stock receipt');
    }

    // Validate rows (Name is required, quantity must be > 0, model is optional)
    const invalidRows = itemsToSubmit.filter(row => (!row.name && !row.sku) || !row.quantity || parseInt(row.quantity, 10) <= 0);
    if (invalidRows.length > 0) {
      return toast.error('Some items are missing a Name/SKU or have an invalid quantity');
    }

    try {
      setIsSubmitting(true);

      // Resolve or auto-create items in public.items directly
      const payloadItems = [];
      for (const row of itemsToSubmit) {
        const normSku = (row.sku || '').trim().toLowerCase();
        const normName = (row.name || '').trim().toLowerCase();

        // 1. Check existing items in database state
        let matched = items.find(i => 
          (normSku && i.sku && i.sku.trim().toLowerCase() === normSku) ||
          (normName && i.name && i.name.trim().toLowerCase() === normName)
        );

        let resolvedItemId = matched?.id;

        // 2. If not found in current items state, insert directly into public.items
        if (!resolvedItemId) {
          const { data: newItem, error: insertError } = await supabase
            .from('items')
            .insert({
              name: row.name || row.sku || 'New Stock Item',
              sku: row.sku || null,
              model: row.model || null,
              unit: t('common.defaultUnit', 'ชิ้น'),
              item_type: row.item_type || 'PARENT',
              parent_sku: row.parent_sku || null,
              description: row.notes || null,
              notes: row.notes || null
            })
            .select('id')
            .single();

          if (insertError) {
            // If duplicate SKU constraint hit, fetch existing ID
            const { data: existing } = await supabase
              .from('items')
              .select('id')
              .eq('sku', row.sku)
              .maybeSingle();
            resolvedItemId = existing?.id;
          } else {
            resolvedItemId = newItem?.id;
          }
        } else if (matched) {
          // If existing item found, sync model & description if missing
          const updatePayload = {};
          if (row.model && (!matched.model || matched.model === '-')) updatePayload.model = row.model;
          if (row.notes && !matched.description) updatePayload.description = row.notes;
          if (row.name && (matched.name === 'PARENT' || matched.name === 'CHILD')) updatePayload.name = row.name;

          if (Object.keys(updatePayload).length > 0) {
            await supabase.from('items').update(updatePayload).eq('id', resolvedItemId);
          }
        }

        payloadItems.push({
          item_id: resolvedItemId,
          sku: row.sku || null,
          parent_sku: row.parent_sku || null,
          item_type: row.item_type || 'PARENT',
          seq_no: row.no ? parseInt(row.no, 10) : null,
          name: row.name || row.sku,
          model: row.model || null,
          quantity: parseInt(row.quantity, 10),
          delivery_to: row.delivery_to || null,
          serial_number: row.serial_number || null,
          part_number: row.part_number || null,
          notes: row.notes || null,
          unit_price: row.unit_price ? parseFloat(row.unit_price) : 0
        });
      }

      // Call Supabase RPC process_stock_in with fallback to direct database insert
      let orderId = null;
      const { data, error: rpcError } = await supabase.rpc('process_stock_in', {
        p_project_id: projectId,
        p_supplier: formData.supplier || null,
        p_po_number: formData.po_number || null,
        p_notes: formData.notes || null,
        p_items: payloadItems
      });

      if (!rpcError && (data?.success || data?.order_id || data?.id)) {
        orderId = data?.order_id || data?.id;
      } else {
        console.warn('process_stock_in RPC error or schema mismatch, executing direct database fallback:', rpcError?.message || rpcError);

        // Direct database insert matching exact active schema
        const { data: orderData, error: orderErr } = await supabase
          .from('stock_in_orders')
          .insert({
            project_id: projectId,
            received_date: new Date().toISOString().split('T')[0],
            created_by: user?.id || null,
            notes: formData.notes || null,
            supplier: formData.supplier || null,
            po_number: formData.po_number || null
          })
          .select()
          .single();

        if (orderErr) throw orderErr;
        orderId = orderData.id;

        const inItems = payloadItems.map(item => ({
          order_id: orderId,
          item_id: item.item_id,
          quantity: item.quantity,
          unit_price: item.unit_price || 0,
          delivery_to: item.delivery_to || null,
          serial_number: item.serial_number || null,
          part_number: item.part_number || null,
          model: item.model || null,
          item_type: item.item_type || 'PARENT',
          parent_id: item.parent_id || null,
          parent_sku: item.parent_sku || null,
          seq_no: item.seq_no || null,
          notes: item.notes || null
        }));

        const { error: itemsErr } = await supabase
          .from('stock_in_items')
          .insert(inItems);

        if (itemsErr) throw itemsErr;

        const inTransactions = payloadItems.map(item => ({
          project_id: projectId,
          item_id: item.item_id,
          quantity: item.quantity,
          transaction_type: 'stock_in',
          reference_type: 'stock_in_order',
          reference_id: orderId,
          notes: item.notes || null,
          created_by: user?.id || null
        }));

        const { error: txErr } = await supabase
          .from('stock_transactions')
          .insert(inTransactions);

        if (txErr) console.warn('Warning inserting stock_transactions:', txErr);
      }

      toast.success(t('stockIn.toasts.created'));

      dispatchStockInNotification({
        orderId: orderId,
        projectId,
        items: payloadItems,
        receivedBy: user?.user_metadata?.full_name || user?.email || 'Warehouse Admin',
        supplier: formData.supplier || '',
        poNumber: formData.po_number || ''
      }).catch(err => console.warn('[StockIn Notification Warning]:', err));

      setIsCreateDialogOpen(false);
      setIsImportPreviewOpen(false);
      fetchData();
    } catch (error) {
      console.error('StockIn Submit Error:', error);
      toast.error(t('stockIn.toasts.createFailed'));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSubmitOrder = async (e) => {
    e.preventDefault();
    if (isSubmitting) return;
    await executeStockInSubmission(formData.project_id, lineItems);
  };

  const viewOrderDetails = async (order) => {
    try {
      const { data, error } = await supabase
        .from('stock_in_items')
        .select('*, items!item_id(name, model, unit, sku)')
        .eq('order_id', order.id);
      if (error) throw error;
      setOrderDetails(data || []);
      setSelectedOrder(order);
    } catch (error) {
      console.error('viewOrderDetails error:', error);
      toast.error('Unable to load receipt details');
    }
  };

  // Filtered preview items for interactive preview search
  const filteredPreviewItems = useMemo(() => {
    if (!debouncedPreviewSearch.trim()) return previewItems;
    const q = debouncedPreviewSearch.toLowerCase();
    return previewItems.filter(i => 
      (i.name && i.name.toLowerCase().includes(q)) ||
      (i.sku && i.sku.toLowerCase().includes(q)) ||
      (i.part_number && i.part_number.toLowerCase().includes(q)) ||
      (i.model && i.model.toLowerCase().includes(q)) ||
      (i.notes && i.notes.toLowerCase().includes(q))
    );
  }, [previewItems, debouncedPreviewSearch]);

  // Calculations
  const totalItemsCount = lineItems.length;
  const totalQuantitySum = lineItems.reduce((acc, row) => acc + (parseInt(row.quantity, 10) || 0), 0);

  const previewParentCount = previewItems.filter(i => i.item_type === 'PARENT').length;
  const previewChildCount = previewItems.filter(i => i.item_type === 'CHILD').length;
  const previewTotalQty = previewItems.reduce((sum, i) => sum + (parseInt(i.quantity, 10) || 0), 0);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight flex items-center gap-2">
            <ArrowDownToLine className="w-7 h-7 text-emerald-600 dark:text-emerald-400" />
            <span>{t('stockIn.title', 'Stock Receipts')}</span>
          </h1>
          <p className="text-muted-foreground mt-2">
            {t('stockIn.subtitle', 'History and records of incoming project materials')}
          </p>
        </div>
        
        {can('stock_in.create') && (
          <div className="flex items-center gap-2.5">
            <input 
              type="file" 
              ref={fileInputRef} 
              accept=".csv" 
              className="hidden" 
              onChange={handleCsvFileUpload} 
            />
            <Button 
              variant="outline"
              className="h-9 px-3 rounded-lg font-semibold text-xs border-border hover:bg-muted text-foreground gap-1.5 cursor-pointer shadow-2xs"
              onClick={() => fileInputRef.current?.click()}
            >
              <Upload className="w-4 h-4" />
              <span>{t('stockIn.importCsv', 'Import CSV (.csv)')}</span>
            </Button>

            <Button 
              className="h-9 px-4 rounded-lg font-semibold text-xs bg-emerald-600 hover:bg-emerald-700 text-white shadow-xs flex items-center gap-2 cursor-pointer shrink-0"
              onClick={handleOpenCreateDialog}
            >
              <Plus className="w-4 h-4 shrink-0" />
              <span>{t('stockIn.directStockIn', 'Receive Stock')}</span>
            </Button>
          </div>
        )}
      </div>

      {/* Search & Filter Toolbar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2.5 flex-1">
          {/* Search Box */}
          <div className="relative flex-1 max-w-lg">
            <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground pointer-events-none" />
            <Input
              type="text"
              aria-label={t('stockIn.searchPlaceholder', 'ค้นหา SKU, ชื่อพัสดุ, ผู้รับ, เลขที่ใบรับเข้า...')}
              placeholder={t('stockIn.searchPlaceholder', 'ค้นหา SKU, ชื่อพัสดุ, ผู้รับ, เลขที่ใบรับเข้า...')}
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              className="pl-8 pr-8 h-9 text-xs rounded-lg bg-background border-border shadow-2xs focus-visible:ring-1"
            />
            {searchInput && (
              <button
                type="button"
                onClick={handleClearSearch}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground p-0.5 rounded cursor-pointer transition-colors"
                title={t('stockIn.clearSearch', 'ล้างคำค้นหา')}
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}
          </div>

          {/* Destination Warehouse Dropdown */}
          <div className="w-full sm:w-56 shrink-0">
            <select
              id="warehouse-filter-select"
              aria-label={t('stockIn.destinationWarehouse', 'คลังสินค้าปลายทาง')}
              value={warehouseFilter}
              onChange={(e) => {
                setWarehouseFilter(e.target.value);
                setCurrentPage(1);
              }}
              className="w-full h-9 px-3 text-xs rounded-lg bg-background border border-border text-foreground shadow-2xs focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer"
            >
              <option value="all">{t('stockIn.allWarehouses', 'คลังทั้งหมด')}</option>
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.project_code ? `[${p.project_code}] ` : ''}{p.name}
                </option>
              ))}
            </select>
          </div>

          {/* Reset Filters Button */}
          {(searchInput || warehouseFilter !== 'all') && (
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={handleResetFilters}
              className="h-9 px-2.5 text-xs text-muted-foreground hover:text-foreground rounded-lg gap-1.5 cursor-pointer shrink-0"
              title={t('common.reset', 'รีเซ็ต')}
            >
              <RotateCcw className="w-3.5 h-3.5" />
              <span className="hidden md:inline">{t('common.reset', 'รีเซ็ต')}</span>
            </Button>
          )}
        </div>

        {/* Results Counter */}
        {(debouncedSearch || warehouseFilter !== 'all') && (
          <div className="text-xs text-muted-foreground shrink-0 flex items-center gap-1.5 font-medium">
            <span className="inline-block w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <span>{t('stockIn.showingResults', { count: totalCount, defaultValue: `พบ ${totalCount} รายการ` })}</span>
          </div>
        )}
      </div>

      {/* Main Stock Receipts Table */}
      <Card className="overflow-hidden rounded-xl bg-card border border-border shadow-xs">
        <div className="overflow-x-auto">
        <Table aria-label={t('stockIn.title', 'รายการรับเข้าพัสดุ')}>
          <TableHeader className="bg-muted/50">
            <TableRow>
              <TableHead>{t('stockIn.receivedDate')}</TableHead>
              <TableHead>{t('stockIn.destinationWarehouse')}</TableHead>
              <TableHead>{t('stockIn.receivedBy')}</TableHead>
              <TableHead className="text-right">{t('common.actions')}</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              <TableRow><TableCell colSpan={4} className="text-center py-12 text-muted-foreground">{t('common.loading')}</TableCell></TableRow>
            ) : orders.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} className="text-center py-12">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <SearchX className="w-10 h-10 text-muted-foreground/40 stroke-1" />
                    <p className="text-sm font-semibold text-foreground">
                      {debouncedSearch || warehouseFilter !== 'all'
                        ? t('stockIn.noOrdersFoundSearch', 'ไม่พบใบรับเข้าพัสดุที่ตรงกับคำค้นหา')
                        : t('common.noData')}
                    </p>
                    {(debouncedSearch || warehouseFilter !== 'all') && (
                      <>
                        <p className="text-xs text-muted-foreground max-w-sm">
                          {t('stockIn.noOrdersFoundDesc', 'ลองตรวจสอบตัวสะกดหรือค้นหาด้วยคำอื่น')}
                        </p>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={handleResetFilters}
                          className="mt-2 h-8 text-xs rounded-lg gap-1.5 cursor-pointer"
                        >
                          <RotateCcw className="w-3 h-3" />
                          <span>{t('stockIn.clearSearch', 'ล้างคำค้นหา')}</span>
                        </Button>
                      </>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ) : (
              orders.map((o) => (
                <TableRow key={o.id} className="hover:bg-muted/20">
                  <TableCell className="text-muted-foreground font-mono">{formatI18nDate(o.created_at, 'dd/MM/yyyy HH:mm')}</TableCell>
                  <TableCell className="font-medium">
                    {o.projects?.project_code ? (
                      <span className="font-mono text-emerald-600 dark:text-emerald-400 font-bold mr-1.5">
                        [{o.projects.project_code}]
                      </span>
                    ) : ''}
                    {o.projects?.name}
                    {o.projects?.location && (
                      <span className="text-xs text-muted-foreground font-normal ml-2">
                        ({o.projects.location})
                      </span>
                    )}

                    {/* Matched item snippet badge (ทางเลือก ข) */}
                    {o.matched_items_snippet && (
                      <div className="mt-1 flex items-center gap-1.5">
                        <span
                          className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border border-emerald-500/20 max-w-md truncate"
                          title={o.matched_items_snippet}
                        >
                          <span className="font-semibold mr-1">{t('stockIn.matchedItem', 'พบพัสดุ')}:</span>
                          {o.matched_items_snippet}
                        </span>
                      </div>
                    )}
                  </TableCell>
                  <TableCell>{o.profiles?.full_name || 'Admin User'}</TableCell>
                  <TableCell className="text-right">
                    <Button size="sm" variant="outline" className="rounded-xl min-h-[44px] sm:min-h-8 h-10 sm:h-8 px-3 text-xs font-semibold cursor-pointer" onClick={() => viewOrderDetails(o)} aria-label={t('common.viewDetails')}>
                      {t('common.viewDetails')}
                    </Button>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
        </div>
      </Card>

      {/* Pagination Footer */}
      {totalPages > 1 && (
        <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-4 py-3 bg-card rounded-xl border border-border shadow-xs text-xs text-muted-foreground select-none">
          <div className="flex items-center gap-2">
            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={currentPage <= 1 || loading}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              className="h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 rounded-lg border-border text-foreground hover:bg-accent disabled:opacity-30 cursor-pointer shadow-xs flex items-center justify-center"
              aria-label={t('common.previous', 'Previous')}
            >
              <ChevronLeft className="w-4 h-4" />
            </Button>

            <div className="flex items-center gap-1.5 font-medium text-foreground">
              <span>{t('items.pagination.page', 'Page')}</span>
              <span className="font-mono font-bold text-foreground px-2 py-0.5 rounded bg-muted/60 border border-border/60">
                {currentPage}
              </span>
              <span>{t('items.pagination.of', 'of')}</span>
              <span className="font-mono font-bold text-foreground">{totalPages}</span>
            </div>

            <Button
              type="button"
              variant="outline"
              size="icon"
              disabled={currentPage >= totalPages || loading}
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              className="h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 rounded-lg border-border text-foreground hover:bg-accent disabled:opacity-30 cursor-pointer shadow-xs flex items-center justify-center"
              aria-label={t('common.next', 'Next')}
            >
              <ChevronRight className="w-4 h-4" />
            </Button>
          </div>

          <div className="text-xs text-muted-foreground font-medium">
            {t('stockIn.totalRecords', 'Total records')}: <span className="font-mono font-bold text-foreground">{totalCount}</span>
          </div>
        </div>
      )}

      {/* ========================================================================= */}
      {/* 1. INTERACTIVE DOPA+USO CSV IMPORT PREVIEW & WAREHOUSE FILTER MODAL */}
      {/* ========================================================================= */}
      <Dialog open={isImportPreviewOpen} onOpenChange={setIsImportPreviewOpen}>
        <DialogContent className="max-w-6xl max-h-[92vh] overflow-hidden flex flex-col p-6 rounded-xl bg-card border border-border shadow-xl">
          <DialogHeader className="pb-3 border-b border-border/40 shrink-0">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
              <div className="flex items-center gap-3">
                <div className="p-2.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20">
                  <FileSpreadsheet className="w-5 h-5" />
                </div>
                <div>
                  <DialogTitle className="text-lg font-bold flex items-center gap-2 text-foreground">
                    <span>{t('stockIn.csvImport.modalTitle')}</span>
                  </DialogTitle>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    File: <strong className="text-foreground">{importFileName || 'CSV Document'}</strong>
                  </p>
                </div>
              </div>

              {/* Summary Badges */}
              <div className="flex items-center gap-1.5 flex-wrap">
                <span className="px-2.5 py-0.5 rounded-lg text-xs font-bold bg-emerald-500/15 text-emerald-600 border border-emerald-500/30 font-mono">
                  {t('stockIn.totalItems')}: {previewItems.length}
                </span>
                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 border border-indigo-500/30">
                  PARENT: {previewParentCount}
                </span>
                <span className="px-2 py-0.5 rounded-lg text-xs font-bold bg-blue-500/15 text-blue-600 dark:text-blue-400 border border-blue-500/30">
                  CHILD: {previewChildCount}
                </span>
                <span className="px-2.5 py-0.5 rounded-lg text-xs font-bold bg-amber-500/15 text-amber-700 dark:text-amber-300 border border-amber-500/30 font-mono">
                  {t('stockIn.totalUnits')}: {formatI18nNumber(previewTotalQty)} {t('common.piece')}
                </span>
              </div>
            </div>
          </DialogHeader>

          <div className="py-4 space-y-4 overflow-y-auto flex-1 pr-1">
            {/* Top Toolbar: Destination Project & Storage Location Selector */}
            <div className="bg-muted/30 p-3.5 rounded-xl border border-border space-y-3">
              <ProjectLocationSelector
                id="preview-project-selector"
                projects={projects}
                value={previewProjectId}
                onChange={handlePreviewProjectChange}
                required={true}
                mode="dual"
                size="sm"
                label="1. Select Project & Storage Location"
                showSummaryCard={false}
              />

              {/* Warehouse Balance Filter Toolbar */}
              <div className="pt-2 border-t border-border/40 flex flex-col sm:flex-row sm:items-center justify-between gap-2.5">
                <div className="space-y-1">
                  <div className="flex items-center gap-1.5 text-xs font-bold text-foreground">
                    <Filter className="w-3.5 h-3.5 text-indigo-600" />
                    <span>{t('stockIn.csvImport.detectedWarehouses')}:</span>
                  </div>
                  
                  {/* Quick Warehouse Pills */}
                  <div className="flex items-center gap-1.5 flex-wrap">
                    <Button
                      type="button"
                      size="xs"
                      variant={selectedQtySource === 'คงเหลือ' ? 'default' : 'outline'}
                      onClick={() => handleChangeQtySource('คงเหลือ')}
                      className={`min-h-[44px] sm:min-h-7 h-auto py-1 px-2.5 rounded-lg text-xs font-bold cursor-pointer transition-all flex items-center gap-1 ${
                        selectedQtySource === 'คงเหลือ'
                          ? 'bg-emerald-600 hover:bg-emerald-700 text-white'
                          : 'border-border/60 hover:bg-muted'
                      }`}
                    >
                      <BarChart3 className="w-3.5 h-3.5" />
                      <span>{t('stockIn.qtySourceTotal')}</span>
                    </Button>

                    {csvDetectedWarehouses.map(wh => {
                      const isSelected = selectedQtySource === wh;
                      return (
                        <Button
                          key={wh}
                          type="button"
                          size="xs"
                          variant={isSelected ? 'default' : 'outline'}
                          onClick={() => handleChangeQtySource(wh)}
                          className={`min-h-[44px] sm:min-h-7 h-auto py-1 px-2.5 rounded-lg text-xs font-bold cursor-pointer transition-all flex items-center gap-1 ${
                            isSelected
                              ? 'bg-indigo-600 hover:bg-indigo-700 text-white shadow-2xs'
                              : 'border-border/60 hover:bg-muted text-foreground'
                          }`}
                        >
                          <Building2 className="w-3.5 h-3.5 text-indigo-500" />
                          <span>{wh}</span>
                        </Button>
                      );
                    })}
                  </div>
                </div>

                {/* Filter Zero Qty Toggle */}
                <Button
                  type="button"
                  size="xs"
                  variant="ghost"
                  onClick={handleToggleOnlyPositive}
                  className="min-h-[44px] sm:min-h-7 h-auto py-1 px-2.5 text-xs font-semibold text-muted-foreground hover:text-foreground gap-1.5 self-start sm:self-auto cursor-pointer"
                >
                  {onlyPositiveFilter ? (
                    <>
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                      <span>{t('stockIn.csvImport.filterPositiveOnly')}</span>
                    </>
                  ) : (
                    <>
                      <Layers className="w-3.5 h-3.5 text-indigo-500" />
                      <span>{t('common.all')}</span>
                    </>
                  )}
                </Button>
              </div>
            </div>

            {/* Active Filter Info Banner */}
            {selectedQtySource !== 'คงเหลือ' && (
              <div className="p-2.5 rounded-xl bg-indigo-500/10 border border-indigo-500/20 text-xs flex items-center justify-between gap-2 animate-in fade-in-50">
                <span className="flex items-center gap-1.5 font-medium text-foreground">
                  <MapPin className="w-4 h-4 text-indigo-600 dark:text-indigo-400" />
                  <span>Showing items and stock balance for: <strong className="text-indigo-600 dark:text-indigo-300">{selectedQtySource}</strong></span>
                </span>
                <span className="font-mono font-bold text-indigo-700 dark:text-indigo-300">
                  {previewItems.length} {previewItems.length === 1 ? 'item' : 'items'} ({previewTotalQty.toLocaleString()} pcs)
                </span>
              </div>
            )}

            {/* Search Bar in Preview */}
            <div className="flex items-center justify-between gap-3">
              <div className="relative w-full sm:w-72">
                <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <Input
                  aria-label={t('stockIn.csvImport.searchPreviewPlaceholder')}
                  placeholder={t('stockIn.csvImport.searchPreviewPlaceholder')}
                  value={previewSearch}
                  onChange={(e) => setPreviewSearch(e.target.value)}
                  className="pl-8 h-8 text-xs rounded-lg"
                />
              </div>

              <span className="text-xs text-muted-foreground">
                Showing {filteredPreviewItems.length} of {previewItems.length} items
              </span>
            </div>

            {/* Preview Items Table */}
            <div className="border border-border rounded-xl overflow-hidden shadow-xs max-h-[44vh] overflow-y-auto overflow-x-auto">
              <Table className="min-w-[700px]" aria-label="CSV Import Preview Table">
                <TableHeader className="bg-muted/60 sticky top-0 z-10 backdrop-blur text-xs">
                  <TableRow className="border-b">
                    <TableHead className="w-[6%] text-center">#</TableHead>
                    <TableHead className="w-[8%]">Type</TableHead>
                    <TableHead className="w-[14%]">Part No. / SKU</TableHead>
                    <TableHead className="w-[32%]">Material / Item Name</TableHead>
                    <TableHead className="w-[15%]">Model / Brand</TableHead>
                    <TableHead className="w-[10%] text-right">{t('common.quantity', 'Quantity')} ({selectedQtySource === 'คงเหลือ' ? t('common.total', 'Total') : selectedQtySource})</TableHead>
                    <TableHead className="w-[12%]">Notes</TableHead>
                    <TableHead className="w-[3%] text-center">Remove</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody className="text-xs">
                  {filteredPreviewItems.map((item, idx) => {
                    const isChild = item.item_type === 'CHILD';

                    return (
                      <TableRow 
                        key={item.tempId || idx}
                        className={`hover:bg-muted/30 transition-colors ${isChild ? 'bg-blue-50/20 dark:bg-blue-950/10' : ''}`}
                      >
                        <TableCell className="text-center font-mono text-muted-foreground">
                          {item.no || idx + 1}
                        </TableCell>

                        <TableCell>
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-bold border ${
                            isChild 
                              ? 'bg-blue-100 text-blue-800 border-blue-300 dark:bg-blue-900/60 dark:text-blue-200' 
                              : 'bg-indigo-100 text-indigo-800 border-indigo-300 dark:bg-indigo-900/60 dark:text-indigo-200'
                          }`}>
                            <span>{isChild ? 'CHILD' : 'PARENT'}</span>
                            {isChild && <CornerDownRight className="w-3 h-3 text-blue-600 dark:text-blue-300 shrink-0" />}
                          </span>
                        </TableCell>

                        <TableCell className="font-mono text-muted-foreground text-xs">
                          {item.part_number || item.sku || '—'}
                        </TableCell>

                        <TableCell className={isChild ? 'pl-6' : ''}>
                          <div className="space-y-0.5">
                            <div className="flex items-center gap-1">
                              {isChild && <CornerDownRight className="w-3.5 h-3.5 text-blue-500 shrink-0 select-none" />}
                              <span className={`font-semibold ${isChild ? 'text-blue-950 dark:text-blue-200' : 'text-foreground'}`}>
                                {item.name}
                              </span>
                            </div>
                            {item.parent_sku && isChild && (
                              <div className="text-xs text-muted-foreground font-mono pl-3">
                                Parent: {item.parent_sku}
                              </div>
                            )}
                          </div>
                        </TableCell>

                        <TableCell className="text-muted-foreground">
                          {item.model || '—'}
                        </TableCell>

                        <TableCell className="text-right font-mono font-bold text-emerald-600 dark:text-emerald-400 text-sm">
                          +{item.quantity}
                        </TableCell>

                        <TableCell className="text-xs text-muted-foreground truncate max-w-[140px]">
                          {item.notes || '—'}
                        </TableCell>

                        <TableCell className="text-center">
                          <Button
                            type="button"
                            variant="ghost"
                            size="icon"
                            onClick={() => setPreviewItems(prev => prev.filter(x => x.tempId !== item.tempId))}
                            className="h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 text-muted-foreground hover:text-destructive rounded-lg cursor-pointer flex items-center justify-center mx-auto"
                            aria-label={t('common.delete', 'ลบรายการ')}
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </Button>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          </div>

          <DialogFooter className="gap-2 sm:justify-between border-t border-border/40 pt-3 shrink-0">
            <Button 
              type="button" 
              variant="outline" 
              className="rounded-lg h-9 px-4 text-xs font-semibold cursor-pointer"
              onClick={() => setIsImportPreviewOpen(false)}
            >
              {t('common.cancel')}
            </Button>

            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={handleApplyPreviewToForm}
                className="rounded-lg h-9 px-4 text-xs font-semibold gap-1.5 border-border text-foreground hover:bg-muted cursor-pointer"
              >
                <span>{t('common.edit')}</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </Button>

              <Button
                type="button"
                disabled={isSubmitting || !previewProjectId || previewItems.length === 0}
                onClick={handleDirectSubmitFromPreview}
                className="rounded-lg h-9 px-4 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold gap-2 shadow-xs cursor-pointer disabled:opacity-50"
              >
                {isSubmitting ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    <span>{t('stockIn.toasts.submitting')}</span>
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="w-4 h-4" />
                    <span>{t('stockIn.csvImport.importBtn', { count: previewItems.length })}</span>
                  </>
                )}
              </Button>
            </div>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* ========================================================================= */}
      {/* 2. DIRECT STOCK RECEIPT EDIT / MANUAL ENTRY MODAL */}
      {/* ========================================================================= */}
      <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
        <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto p-6 rounded-xl bg-card border border-border shadow-xl">
          <form onSubmit={handleSubmitOrder}>
            <DialogHeader className="border-b border-border/40 pb-3">
              <DialogTitle className="text-xl font-bold flex items-center gap-2">
                <ArrowDownToLine className="w-6 h-6 text-emerald-600 dark:text-emerald-400" />
                <span>Direct Stock Receipt (Parent/Child Hierarchy)</span>
              </DialogTitle>
            </DialogHeader>

            <div className="space-y-6 py-4">
              {/* Destination Project & Storage Location Selection */}
              <div className="bg-muted/30 p-4 rounded-xl border border-border space-y-3">
                <ProjectLocationSelector
                  id="direct-project-selector"
                  projects={projects}
                  value={formData.project_id}
                  onChange={handleDirectProjectChange}
                  required={true}
                  mode="dual"
                  label="Project & Storage Location"
                  showSummaryCard={true}
                />

                {/* CSV Detected Warehouse Balance Selector (If CSV has been imported) */}
                {csvDetectedWarehouses.length > 0 && (
                  <div className="pt-2 border-t border-border/40 flex items-center justify-between gap-2 flex-wrap text-xs">
                    <span className="font-bold text-muted-foreground flex items-center gap-1">
                      <SlidersHorizontal className="w-3.5 h-3.5 text-indigo-500" />
                      <span>Quick filter by file warehouse:</span>
                    </span>
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <Button
                        type="button"
                        size="xs"
                        variant="outline"
                        onClick={() => {
                          const allAgg = filterAndAggregateWarehouseItems(rawParsedCsvItems, 'คงเหลือ', { filterZeroQty: false });
                          setLineItems(allAgg);
                          toast.success('Showing total balance across all warehouses');
                        }}
                        className="min-h-[44px] sm:min-h-7 h-auto py-1 px-2.5 text-xs rounded-lg font-bold flex items-center gap-1"
                      >
                        <BarChart3 className="w-3.5 h-3.5 text-emerald-600" />
                        <span>Total Balance</span>
                      </Button>
                      {csvDetectedWarehouses.map(wh => (
                        <Button
                          key={wh}
                          type="button"
                          size="xs"
                          variant="outline"
                          onClick={() => {
                            const whAgg = filterAndAggregateWarehouseItems(rawParsedCsvItems, wh, { filterZeroQty: true });
                            setLineItems(whAgg);
                            toast.success(`Filtered for [${wh}]: ${whAgg.length} item(s)`);
                          }}
                          className="min-h-[44px] sm:min-h-7 h-auto py-1 px-2.5 text-xs rounded-lg font-bold border-indigo-500/30 text-indigo-700 dark:text-indigo-300 hover:bg-indigo-500/10 flex items-center gap-1"
                        >
                          <Building2 className="w-3.5 h-3.5 text-indigo-500" />
                          <span>{wh}</span>
                        </Button>
                      ))}
                    </div>
                  </div>
                )}
              </div>

              {/* CSV Tools Action Bar */}
              <div className="flex flex-wrap items-center justify-between gap-3 bg-emerald-500/10 p-3 rounded-xl border border-emerald-500/20">
                <div className="flex items-center gap-2 text-sm text-emerald-900 dark:text-emerald-200">
                  <Upload className="w-4 h-4 text-emerald-600" />
                  <span className="font-semibold">Import CSV with Parent-Child structure or multi-warehouse columns (UTF-8 BOM)</span>
                </div>
                <div className="flex items-center gap-2">
                  <Button 
                    type="button" 
                    variant="outline" 
                    size="sm"
                    className="h-8 text-xs gap-1 border-emerald-500/30 hover:bg-emerald-500/10 font-bold"
                    onClick={handleDownloadCsvTemplate}
                  >
                    <Download className="w-3.5 h-3.5" /> Download CSV Template
                  </Button>
                  
                  <Button 
                    type="button" 
                    size="sm"
                    className="h-8 text-xs gap-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold cursor-pointer"
                    onClick={() => fileInputRef.current?.click()}
                  >
                    <Upload className="w-3.5 h-3.5" /> Import CSV File
                  </Button>
                </div>
              </div>

              {/* Dynamic Line Items Section */}
              <div className="space-y-3">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2">
                  <h3 className="font-semibold text-sm flex items-center gap-2">
                    Incoming Material Items ({lineItems.length} {lineItems.length === 1 ? 'item' : 'items'})
                  </h3>
                  <div className="flex gap-2">
                    <Button 
                      type="button" 
                      variant="outline" 
                      size="sm"
                      className="h-8 text-xs gap-1.5 px-3 rounded-lg text-emerald-700 dark:text-emerald-300 border-emerald-500/30 hover:bg-emerald-500/10 font-bold shadow-2xs cursor-pointer"
                      onClick={() => handleAddLineItem('PARENT')}
                    >
                      <Plus className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
                      <span>Add Parent Item</span>
                    </Button>
                    <Button 
                      type="button" 
                      variant="outline" 
                      size="sm"
                      className="h-8 text-xs gap-1.5 px-3 rounded-lg text-blue-700 dark:text-blue-300 border-blue-500/30 hover:bg-blue-500/10 font-bold shadow-2xs cursor-pointer"
                      onClick={() => {
                        const lastParent = lineItems.slice().reverse().find(i => i.item_type === 'PARENT');
                        handleAddLineItem('CHILD', lastParent?.sku || '');
                      }}
                    >
                      <Plus className="w-3.5 h-3.5 text-blue-600 dark:text-blue-400" />
                      <span>Add Child Item</span>
                    </Button>
                  </div>
                </div>

                <div className="border border-border rounded-xl overflow-x-auto shadow-xs max-h-[44vh] overflow-y-auto">
                  <Table aria-label="Direct Entry Line Items Table">
                    <TableHeader className="bg-muted/40 sticky top-0 z-10 backdrop-blur">
                      <TableRow className="text-xs">
                        <TableHead className="w-[8%] min-w-[75px]">Type</TableHead>
                        <TableHead className="w-[10%] min-w-[100px]">Item SKU</TableHead>
                        <TableHead className="w-[9%] min-w-[95px]">Parent SKU</TableHead>
                        <TableHead className="w-[20%] min-w-[160px]">Item Name *</TableHead>
                        <TableHead className="w-[12%] min-w-[110px]">Model / Brand</TableHead>
                        <TableHead className="w-[7%] min-w-[65px] text-center">Quantity *</TableHead>
                        <TableHead className="w-[10%] min-w-[95px]">S/N</TableHead>
                        <TableHead className="w-[10%] min-w-[95px]">Part No.</TableHead>
                        <TableHead className="w-[10%] min-w-[110px]">Notes</TableHead>
                        <TableHead className="w-[4%] min-w-[45px] text-center">Remove</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {lineItems.length === 0 ? (
                        <TableRow>
                          <TableCell colSpan={10} className="text-center py-6 text-muted-foreground text-sm">
                            No items added yet. Click &quot;+ Add Parent Item&quot; or import a CSV file
                          </TableCell>
                        </TableRow>
                      ) : (
                        lineItems.map((row) => {
                          const isChild = row.item_type === 'CHILD';
                          return (
                            <TableRow key={row.tempId} className={isChild ? "bg-blue-50/30 dark:bg-blue-950/10" : ""}>
                              <TableCell className="align-top">
                                <select 
                                  aria-label={`Item Type ${row.name || row.tempId}`}
                                  value={row.item_type} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'item_type', e.target.value)}
                                  className={`h-9 w-full rounded-lg border px-1 text-xs font-bold ${isChild ? 'bg-blue-100 text-blue-800 border-blue-300 dark:bg-blue-900/60 dark:text-blue-200 dark:border-blue-700' : 'bg-emerald-100 text-emerald-800 border-emerald-300 dark:bg-emerald-900/60 dark:text-emerald-200 dark:border-emerald-700'}`}
                                >
                                  <option value="PARENT">PARENT</option>
                                  <option value="CHILD">CHILD</option>
                                </select>
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`SKU ${row.name || row.tempId}`}
                                  placeholder="SKU-001" 
                                  value={row.sku} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'sku', e.target.value)} 
                                  className="h-9 text-xs font-mono font-semibold rounded-lg"
                                />
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Parent SKU ${row.name || row.tempId}`}
                                  placeholder={isChild ? "Parent SKU" : "-"} 
                                  disabled={!isChild}
                                  value={row.parent_sku} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'parent_sku', e.target.value)} 
                                  className="h-9 text-xs font-mono disabled:opacity-40 rounded-lg"
                                />
                              </TableCell>

                              <TableCell className={`align-top ${isChild ? 'pl-6' : ''}`}>
                                <div className="flex items-center gap-1">
                                  {isChild && <CornerDownRight className="w-3.5 h-3.5 text-blue-500 shrink-0 inline-block select-none" aria-hidden="true" />}
                                  <Input 
                                    aria-label={`Item Name ${row.tempId}`}
                                    required
                                    placeholder={isChild ? "Enter child item name" : "Enter item name"} 
                                    value={row.name} 
                                    onChange={e => handleUpdateLineItem(row.tempId, 'name', e.target.value)} 
                                    className={`h-9 text-xs rounded-lg ${isChild ? 'font-medium text-blue-950 dark:text-blue-200' : 'font-semibold'}`}
                                  />
                                </div>
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Model ${row.name || row.tempId}`}
                                  placeholder="Model (optional)" 
                                  value={row.model} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'model', e.target.value)} 
                                  className="h-9 text-xs font-medium rounded-lg"
                                />
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Quantity ${row.name || row.tempId}`}
                                  type="number" 
                                  min="1" 
                                  required 
                                  value={row.quantity ?? ''} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'quantity', e.target.value)} 
                                  className="h-9 text-center text-xs font-bold px-1 rounded-lg [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
                                />
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Serial Number ${row.name || row.tempId}`}
                                  placeholder="S/N (optional)" 
                                  value={row.serial_number} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'serial_number', e.target.value)} 
                                  className="h-9 text-xs font-mono rounded-lg"
                                />
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Part Number ${row.name || row.tempId}`}
                                  placeholder="Part No." 
                                  value={row.part_number} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'part_number', e.target.value)} 
                                  className="h-9 text-xs font-mono rounded-lg"
                                />
                              </TableCell>

                              <TableCell className="align-top">
                                <Input 
                                  aria-label={`Notes ${row.name || row.tempId}`}
                                  placeholder="Notes" 
                                  value={row.notes} 
                                  onChange={e => handleUpdateLineItem(row.tempId, 'notes', e.target.value)} 
                                  className="h-9 text-xs rounded-lg"
                                />
                              </TableCell>

                              <TableCell className="align-top text-center">
                                <Button 
                                  type="button" 
                                  variant="ghost" 
                                  size="sm" 
                                  className="h-8 w-8 min-h-[44px] min-w-[44px] sm:min-h-8 sm:min-w-8 p-0 text-muted-foreground hover:text-destructive cursor-pointer flex items-center justify-center mx-auto"
                                  onClick={() => handleRemoveLineItem(row.tempId)}
                                  aria-label={t('common.delete', 'ลบรายการ')}
                                >
                                  <Trash2 className="w-4 h-4" />
                                </Button>
                              </TableCell>
                            </TableRow>
                          );
                        })
                      )}
                    </TableBody>
                  </Table>
                </div>
              </div>

              {/* Receipt Summary Calculation */}
              <div className="flex items-center justify-between bg-muted/30 p-3 rounded-xl border border-border text-sm">
                <div className="flex gap-6 text-xs sm:text-sm font-medium flex-wrap">
                  <span>Total Items: <strong className="text-foreground font-bold">{totalItemsCount}</strong></span>
                  <span>Parent Items: <strong className="text-emerald-600 dark:text-emerald-400 font-bold">{lineItems.filter(i => i.item_type === 'PARENT').length}</strong></span>
                  <span>Child Items: <strong className="text-blue-600 dark:text-blue-400 font-bold">{lineItems.filter(i => i.item_type === 'CHILD').length}</strong></span>
                  <span>Total Quantity: <strong className="text-emerald-600 dark:text-emerald-400 font-bold">{totalQuantitySum}</strong> pcs</span>
                </div>
              </div>
            </div>

            <DialogFooter className="gap-2 sm:gap-0 border-t border-border/40 pt-4">
              <Button type="button" variant="outline" onClick={() => setIsCreateDialogOpen(false)} disabled={isSubmitting} className="rounded-lg h-9 px-4 text-xs font-semibold">
                {t('common.cancel')}
              </Button>
              <Button 
                type="submit" 
                className="h-9 px-4 rounded-lg font-semibold text-xs bg-emerald-600 hover:bg-emerald-700 text-white shadow-xs flex items-center gap-2 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed" 
                disabled={isSubmitting || !formData.project_id || lineItems.some(i => (!i.name && !i.sku))}
              >
                {isSubmitting ? (
                  <>
                    <RefreshCw className="w-4 h-4 shrink-0 animate-spin" />
                    <span>{t('stockIn.toasts.submitting')}</span>
                  </>
                ) : (
                  <>
                    <Check className="w-4 h-4 shrink-0" />
                    <span>{t('stockIn.completeStockIn')}</span>
                  </>
                )}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* ========================================================================= */}
      {/* 3. ORDER DETAILS DIALOG */}
      {/* ========================================================================= */}
      <StockInOrderDetailModal
        selectedOrder={selectedOrder}
        orderDetails={orderDetails}
        onClose={() => setSelectedOrder(null)}
      />
    </div>
  );
};

export default StockIn;
